const BLOCKS = {
  b_sk:{name:"Скорость",lede:"Короткие отрезки, максимальное усилие, длинный отдых. Работаем свежими, а не на терпении.",levels:{
    sk_n:{level:"Новичок",vol:"1300–1600 м",w:[
      {n:1,vol:1300,note:"Первая скоростная тренировка устроена максимально просто: короткие отрезки, много отдыха, каж…",story:"Первая скоростная тренировка устроена максимально просто: короткие отрезки, много отдыха, каждый отрезок в полную силу. Быстро плыть — это отдельный навык, и учиться ему нужно на свежих мышцах. Если к концу серии вы плывёте медленнее, чем в начале, значит отдыхали мало, а не старались плохо.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: нечётные — упражнение на координацию, чётные — плавание чуть быстрее"]],main:[[200,"8х25м кроль в полную силу, i45","Отдых обязательно выдерживать полностью, даже если кажется, что вы уже готовы. Скорость тренируется отдыхом не меньше, чем работой."],[100,"100м откуп спокойно на спине"],[100,"4х25м основной стиль в полную силу, i45","На своём стиле следите не за темпом, а за тем, чтобы движения не превращались в суету. Быстро — это длинно и мощно, а не часто и мелко."],[100,"100м откуп спокойно"],[100,"4х25м кроль в полную силу, i45","Последние отрезки — проверка. Если они заметно медленнее первых, в следующий раз сделайте серию короче."]],cool:[[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"],[100,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:1350,note:"У большинства начинающих ноги не толкают, а тормозят",story:"У большинства начинающих ноги не толкают, а тормозят. Здесь мы разбираем их отдельно и коротко: несколько быстрых отрезков с полным отдыхом. Цель не выносливость ног, а умение работать ими часто и от бедра — именно это потом добавляет скорость в кроле.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской спокойно"],[100,"4х25м ноги в ластах, i20"]],main:[[200,"8х25м ноги с доской в полную силу, i45","Колени не должны выходить из воды. Движение идёт от бедра, стопа расслаблена и вытянута — как только на поверхности появились колени, отдохните подольше."],[100,"100м откуп спокойно на спине"],[150,"6х25м ноги на спине без доски в полную силу, i45","Руки вдоль тела, живот подобран, таз у поверхности. На спине сразу видно, если ноги работают вниз, а не назад: тело начинает складываться."],[100,"100м откуп спокойно"],[100,"4х25м ноги в ластах с максимальной частотой, i30","Ласты помогают почувствовать правильное движение. Запомните это ощущение — без ласт нужно повторить его же, только медленнее."]],cool:[[100,"100м спина: работа двумя руками одновременно, ноги почти без усилия"],[100,"100м кроль с колобашкой, ноги отдыхают"],[100,"100м произвольно"]]},
      {n:3,vol:1300,note:"Колобашка выключает ноги, и вся работа остаётся на руках",story:"Колобашка выключает ноги, и вся работа остаётся на руках. Для начинающего это лучший способ почувствовать, что такое опора: без ног обмануть себя не получится. Отрезки короткие, потому что руки устают быстро, а плавать быстро уставшими руками смысла нет.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м руки с колобашкой спокойно"],[100,"4х25м i20: первые два на кулаках, вторые два руки с колобашкой спокойно — настраиваем захват"]],main:[[200,"8х25м руки с колобашкой в полную силу, i45","Без ног таз проваливается. Держите его у поверхности напряжением живота: если тело складывается, гребок толкает воду вниз, а не назад."],[100,"100м откуп спокойно на спине"],[100,"4х25м руки с колобашкой и мал лоп в полную силу, i45","С лопатками легко потащить воду прямой рукой. Локоть остаётся выше кисти — если чувствуете нагрузку в плече, снимите лопатки."],[100,"100м откуп спокойно"],[100,"4х25м руки с колобашкой без лопаток в полную силу, i45","Ради этой серии лопатки и надевались. Опора должна чувствоваться такой же: если рука проскальзывает, значит захват держался на инвентаре."]],cool:[[100,"100м в трубке ноги кролем спокойно"],[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"]],safe:"Лопатки вместе с колобашкой дают самую большую нагрузку на плечо: ноги не поддерживают тело. На этом уровне лопатки только маленькие и не больше 100 м за тренировку. При любой боли в плече серия плывётся без них."},
      {n:4,vol:1500,note:"Поворот — самое дешёвое место, где начинающий может выиграть время",story:"Поворот — самое дешёвое место, где начинающий может выиграть время. Пока техника плавания только строится, стенка отдаёт секунды почти бесплатно. Сначала разбираем выход из поворота, потом заход в него, и каждый отрезок содержит ровно один поворот.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: подход к стенке спокойно и поворот без ускорения — отрабатываем сам разворот"]],main:[[300,"6х50м кроль i45: первые 25м спокойно, вторые 25м в полную силу. Работаем выход из поворота","После толчка тело должно быть вытянуто в струнку: руки за головой, одна кисть на другой, голова между руками. Гребок начинается только после всплытия."],[100,"100м откуп спокойно на спине"],[300,"6х50м кроль i45: первые 25м в полную силу, вторые 25м спокойно. Работаем заход в стенку","Не «доплывайте» до бортика. Последний гребок остаётся полным, и только после него начинается группировка — иначе вы тормозите заранее."],[100,"100м откуп спокойно"]],cool:[[100,"100м скольжений: толчок от бортика и скольжение до полной остановки, остаток отрезка спокойно (4х25м)"],[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:5,vol:1300,note:"Старт — это несколько метров, которые проплываются быстрее, чем вы способны плыть",story:"Старт — это несколько метров, которые проплываются быстрее, чем вы способны плыть. Для начинающего здесь важна не сила толчка, а вход в воду: если тело шлёпнуло по поверхности, скорость теряется мгновенно. Отрезки очень короткие, отдых большой — работаем над качеством, а не над усталостью.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i30: со старта спокойно — отрабатываем вход в воду и первые метры без максимума"]],main:[[150,"6х25м: старт + 10м максимум, дальше спокойно до стенки, i60","Смотрите на точку входа, а не вперёд. Руки вытянуты, голова между ними, тело входит в одну «дырку» в воде — брызг должно быть минимум."],[150,"150м откуп: 100м спина + 50м кроль"],[150,"6х25м со старта в полную силу, i60","Первый гребок начинается после выхода на поверхность. Если начать грести под водой на всплытии, скорость толчка теряется впустую."],[150,"150м откуп спокойно"]],cool:[[100,"100м скольжений с бортика: толчок, длинное скольжение, остаток отрезка спокойно"],[100,"100м спина: работа двумя руками одновременно"],[100,"100м произвольно"]],safe:"Стартовые прыжки выполняются только там, где глубина в зоне приводнения от 1,8 м, тумба и бортик сухие, дорожка свободна. Если прыжок с тумбы ещё не освоен, сначала пройдите поэтапное обучение стартовому прыжку, а серию плывите со старта из воды."},
      {n:6,vol:1300,note:"Быстро плыть можно не только кролем",story:"Быстро плыть можно не только кролем. Здесь каждая серия плывётся своим стилем, и внутри неё скорость растёт от отрезка к отрезку: спокойно, средне, быстро, максимум. Такая ступенька учит разгоняться постепенно, а не выпрыгивать с первого гребка и потом терпеть.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: по одному отрезку спиной и брассом, два отрезка кролем, спокойно"]],main:[[400,"3 серии по 4х25м i30, каждая серия своим стилем — спина, брасс, кроль: первый отрезок спокойно, второй средне, третий быстро, четвёртый максимум. Между сериями 50м откуп спокойно","Ступеньки должны быть примерно одинаковыми. Если первый отрезок уже быстрый, расти будет некуда — начинайте спокойнее, чем кажется нужным."],[100,"100м откуп спокойно на спине"],[100,"4х25м кроль в полную силу, i45","Здесь ступеней нет: максимум с первого гребка. Тело уже разогрето сериями и включается легче."]],cool:[[200,"200м упражнения из курса: 100м на кроль + 100м на спину"],[100,"100м произвольно"]]},
      {n:7,vol:1600,note:"В заплыве ускоряться приходится в разных местах: на старте, в середине, на финише",story:"В заплыве ускоряться приходится в разных местах: на старте, в середине, на финише. Здесь быстрый участок каждый раз стоит в новой точке пятидесятки, а остальное плывётся свободно. Так тело учится включаться по команде, а не разгоняться десять метров.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: 15м спокойно + 10м ускорение"]],main:[[200,"4х50м кроль i45: 15м максимально + 35м свободно","Ускорение с места: важна частота, а не размах. Считайте, за сколько гребков проходите первые 15 метров."],[100,"100м откуп спокойно на спине"],[200,"4х50м кроль i45: 15м свободно + 20м максимально + 15м свободно","Ускорение с хода труднее всего: скорость уже есть, и добавлять надо поверх неё. Включайтесь сразу, а не постепенно."],[100,"100м откуп спокойно"],[200,"4х50м кроль i45: 35м свободно + 15м максимально на финиш","Не поднимайте голову перед стенкой. Взгляд вниз, последний гребок полный — привычка смотреть на бортик стоит времени в каждом заплыве."],[100,"100м откуп спокойно"]],cool:[[100,"100м спина: работа двумя руками одновременно"],[100,"100м в трубке ноги кролем"],[100,"100м произвольно"]]},
      {n:8,vol:1500,note:"Плыть на одной скорости умеют все, а вот переключаться — почти никто",story:"Плыть на одной скорости умеют все, а вот переключаться — почти никто. Внутри отрезка темп меняется: половина быстро, половина спокойно. Спокойная часть здесь не отдых, а проверка, умеете ли вы сбрасывать усилие, не разваливая технику.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: через одну — спина и кроль"]],main:[[300,"6х50м кроль i45: 25м быстро + 25м спокойно","Спокойная половина — не выключение. Тело остаётся вытянутым, гребок длинным: учимся сбрасывать усилие, не теряя положения."],[100,"100м откуп спокойно на спине"],[300,"6х50м i45: 25м спина в полную силу, затем 25м кроль спокойно","Смена стиля должна быть мгновенной. После спины первые гребки кролем часто идут вслепую — сознательно поймайте опору с первого движения."],[100,"100м откуп спокойно"]],cool:[[100,"100м спина спокойно"],[100,"100м упражнения из курса на кроль"],[100,"100м кроль на минимальное число гребков"]]},
      {n:9,vol:1400,note:"Каждый вдох на скорости стоит времени: голова поворачивается, тело чуть тормозит",story:"Каждый вдох на скорости стоит времени: голова поворачивается, тело чуть тормозит. Здесь мы аккуратно учимся дышать реже — не задерживать дыхание на пределе, а именно сокращать число вдохов на коротких отрезках. Всё выполняется в спокойном режиме и с большим отдыхом.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м кроль i20 с дыханием на 3 гребка"]],main:[[200,"8х25м кроль в полную силу, два вдоха на отрезке, i45","Вдох делается в первой половине отрезка. Голова поворачивается вбок, а не поднимается вперёд — одно очко остаётся в воде."],[100,"100м откуп спокойно на спине"],[100,"4х25м кроль в полную силу, один вдох на отрезке, i60","Если начинает не хватать воздуха — сделайте лишний вдох. Терпеть до предела здесь не нужно и не полезно."],[100,"100м откуп спокойно"],[200,"4х50м кроль i45: 25м максимум с дыханием на 3 гребка + 25м свободно","На второй половине дышите как удобно. Задача — восстановиться на ходу, не останавливаясь у бортика."]],cool:[[100,"100м спина спокойно, дыхание полностью свободное"],[100,"100м в трубке ноги кролем"],[100,"100м произвольно"]],safe:"Не гипервентилировать перед отрезками и не задерживать дыхание до предела. Не выполнять эту работу в одиночку. При головокружении, потемнении в глазах или любом дискомфорте — прекратить серию и перейти к спокойному плаванию."},
      {n:10,vol:1450,note:"Финиш — единственное место, где начинающий теряет время буквально на ровном месте: поднимает…",story:"Финиш — единственное место, где начинающий теряет время буквально на ровном месте: поднимает голову, смотрит на стенку, укорачивает последний гребок. Здесь каждый отрезок заканчивается быстрым участком и полноценным касанием, и эта привычка потом переносится в любой заплыв.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: последние 10м каждого отрезка — ускорение"]],main:[[300,"6х50м кроль i45: 35м спокойно + 15м максимально быстро на финиш","Момент включения решите заранее и держите его на всех отрезках. Скорость должна расти резко, а не «когда получится»."],[100,"100м откуп спокойно на спине"],[150,"6х25м кроль в полную силу до касания стенки, i45","Касание — часть отрезка. Не подглядывайте на бортик: последний гребок такой же полный, как первый."],[100,"100м откуп спокойно"],[100,"4х25м основной стиль в полную силу на финиш, i45","На своём стиле ошибка та же: гребок укорачивается перед стенкой. Сознательно доводите руку до конца."]],cool:[[100,"100м спина: работа двумя руками одновременно"],[100,"100м скольжений с бортика"],[100,"100м произвольно"]]},
      {n:11,vol:1400,note:"Мощность гребка проще всего почувствовать через контраст",story:"Мощность гребка проще всего почувствовать через контраст. Сначала мы усиливаем опору маленькими лопатками, а потом снимаем их — и рука какое-то время помнит, как надо держать воду. Именно ради этих последних отрезков без лопаток и делается вся тренировка.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м кроль i20 в прогресс: от спокойного к быстрому"]],main:[[200,"8х25м кроль с мал лоп в полную силу, i45","С лопатками легко начать частить впустую. Гребок остаётся длинным: лучше меньше гребков с полной опорой, чем много коротких и суетливых."],[100,"100м откуп спокойно на спине"],[200,"4х50м кроль с мал лоп i60: 25м максимум + 25м свободно","Лопатка подчёркивает провал локтя. Кисть всегда ниже локтя — с лопаткой это чувствуется отчётливее, чем без неё."],[100,"100м откуп спокойно"],[100,"4х25м кроль без лопаток в полную силу, i45","Запомните ощущение опоры и удержите ту же длину гребка. Если рука проскальзывает — значит захват держался на лопатке."]],cool:[[100,"100м кроль на минимальное число гребков"],[100,"100м спина спокойно"],[100,"100м упражнения из курса на кроль"]],safe:"Лопатки только маленькие и не больше 200 м за тренировку. Если в плече появляется дискомфорт, серия плывётся без лопаток — на этом уровне техника важнее нагрузки."},
      {n:12,vol:1400,note:"Чтобы плыть быстро, нужно хотя бы раз почувствовать, что такое быстро",story:"Чтобы плыть быстро, нужно хотя бы раз почувствовать, что такое быстро. Ласты дают скорость выше вашей собственной, и тело успевает запомнить положение на этой скорости: таз высоко, тело ровное. Дальше задача повторить то же ощущение уже без ласт.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги в ластах спокойно"],[100,"4х25м в ластах i20: через одну — спина и кроль"]],main:[[200,"8х25м кроль в ластах в полную силу с высокой частотой гребка, i45","Ласты дают скорость, а ваша задача — руки. Не позволяйте ластам везти вас: гребки должны идти чаще обычного."],[100,"100м откуп спокойно на спине"],[200,"4х50м i60: 25м в ластах максимум + 25м свободно","Обратите внимание на положение тела на скорости: таз выше, тело ровнее. Это образец, к которому нужно вернуться без ласт."],[100,"100м откуп спокойно"],[100,"4х25м кроль без ласт в полную силу, i45","Повторите ту же частоту гребка, что была в ластах. Скорость будет ниже — это нормально, важно ощущение темпа."]],cool:[[100,"100м в трубке ноги брассом спокойно"],[100,"100м кроль с колобашкой"],[100,"100м произвольно, дыхание свободное"]]},
      {n:13,vol:1300,note:"Скорость складывается из двух вещей: как часто вы гребёте и сколько проплываете за один гребок",story:"Скорость складывается из двух вещей: как часто вы гребёте и сколько проплываете за один гребок. Обычно новичок улучшает одно за счёт другого и стоит на месте. Здесь мы разводим эти параметры и на каждом отрезке считаем и гребки, и время — так становится видно, где именно ваш запас.",warm:[[200,"200м спокойно: 100м кроль с подсчётом гребков + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м кроль i20 на минимальное число гребков"]],main:[[100,"4х25м кроль в полную силу, записать время и число гребков, i60","Это ваша исходная точка. Записывайте оба числа — дальше вся тренировка строится вокруг них."],[100,"4х25м кроль: то же время, но на 1 гребок меньше, i60","Работаем над длиной. Помогает более длинное вытягивание вперёд после входа руки и доведение гребка до бедра."],[100,"4х25м кроль: то же число гребков, но быстрее, i60","Работаем над частотой при сохранении длины. Ускоряться нужно окончанием гребка, а не входом руки."],[100,"100м откуп спокойно на спине"],[100,"4х25м кроль с максимальной частотой, i45","Здесь длину не считаем — только частоту. Сравните ощущение с предыдущими сериями: где скорость выше, там и ваш резерв."],[100,"100м откуп спокойно"]],cool:[[100,"4х25м кроль на минимальное число гребков, i20"],[100,"100м спина спокойно"],[100,"100м в трубке ноги кролем"]]},
      {n:14,vol:1500,note:"Комплексное плавание пугает начинающих переходами: кажется, что нужно успеть слишком много",story:"Комплексное плавание пугает начинающих переходами: кажется, что нужно успеть слишком много. На деле переход — это одно касание и один разворот, и он прекрасно тренируется отдельно. Здесь мы разгоняем стиль перед сменой, чтобы переход приходилось делать не в спокойном темпе.",warm:[[200,"200м спокойно: 100м спина + 100м брасс"],[100,"100м ноги с доской"],[100,"4х25м i20: через одну — спина и брасс"]],main:[[300,"6х50м i45: 25м спина в полную силу, затем 25м брасс спокойно. Работаем сам переход","До касания стенки нужно оставаться на спине — это требование правил. Разворот начинается только после того, как рука коснулась бортика."],[100,"100м откуп спокойно"],[300,"6х50м i45: 25м брасс в полную силу, затем 25м кроль спокойно. Работаем сам переход","Касание в брассе — обеими руками одновременно. После разворота первые метры кроля плывутся с акцентом на ноги, иначе таз останется внизу."],[100,"100м откуп спокойно"]],cool:[[200,"200м упражнения из курса: 100м на спину + 100м на брасс"],[100,"100м произвольно"]]},
      {n:15,vol:1600,note:"Финальная тренировка блока собирает всё вместе: быстрые переходы, смену стилей и один контрол…",story:"Финальная тренировка блока собирает всё вместе: быстрые переходы, смену стилей и один контрольный комплекс на время. Сто метров комплексом — понятная цель для начинающего и удобная точка отсчёта: запишите время и вернитесь к нему через месяц.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: спина, брасс и два отрезка кролем"]],main:[[300,"6х50м i45: 25м брасс в полную силу, затем 25м кроль в полную силу","Самый неудобный переход: брасс уводит тело вниз, кроль требует высокого положения. Первые гребки кролем — с активными ногами."],[100,"100м откуп спокойно на спине"],[200,"4х50м комплекс i60: 25м спина + 25м брасс","Здесь скорость не нужна, нужна чистота перехода. Касание, разворот, первый полный гребок — без паузы посередине."],[100,"100м откуп спокойно"],[100,"100м комплекс на время: по 25м каждым стилем, i2:00","Ваша контрольная точка. Если дельфин пока не освоен, первый отрезок плывите на спине и отметьте это — главное сравнивать с собой в одинаковых условиях."],[100,"100м откуп спокойно"]],cool:[[100,"100м спина спокойно"],[100,"100м скольжений с бортика"],[100,"100м кроль на минимальное число гребков"]]}
    ]},
    sk_s:{level:"Средний",vol:"1800–2300 м",w:[
      {n:1,vol:1800,note:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость",story:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость. Половина работы кролем, половина — своим стилем, потому что скорость нужна не только в кроле. Задача не терпеть, а каждый раз стартовать свежим: если время падает к концу серии, не хватило отдыха, а не характера.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской спокойно"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i20: нечётные — упражнение на координацию, чётные — плавание в прогресс"]],main:[[200,"8х25м кроль в полную силу, режим 1:00","Считайте гребки на каждом отрезке. К концу серии их число не должно вырасти больше чем на один-два: если выросло, скорость держится частотой, а гребок уже разваливается."],[200,"200м откуп: 100м спина спокойно + 100м кроль на минимальное число гребков"],[200,"4х50м основной стиль в полную силу, режим 2:00","На своём стиле техника рассыпается первой. Следите за длиной гребка, а не за частотой: на скорости выигрывает тот, кто остаётся техничным."],[100,"100м откуп спокойно на спине"],[100,"4х25м кроль в полную силу, режим 1:00","Последние отрезки — проверка. Если они медленнее первых, в следующий раз сокращайте серию, а не отдых."]],cool:[[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"],[100,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:1900,note:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго",story:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго. Здесь наоборот: короткие максимальные отрезки, высокая частота и разные положения тела. После такой тренировки обычный кроль ощущается легче, потому что ноги перестают быть тормозом и начинают толкать.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской спокойно: 100м кроль + 100м брасс"],[200,"4х50м ноги в ластах в прогресс, i30"],[100,"4х25м ноги дельфином на спине в ластах, i20"]],main:[[200,"8х25м ноги кролем без доски в полную силу, режим 1:00","Колени не выходят из воды, движение идёт от бедра. На высокой частоте это теряется первым: как только на поверхности появились колени, добавьте себе 15 секунд отдыха."],[200,"200м откуп спокойно на спине"],[300,"6х50м ноги, режим 1:30: 25м дельфином на груди максимум + 25м на спине свободно","Дельфин на максимуме идёт от груди и таза, а не от коленей. Стопы вместе, амплитуда небольшая — удар должен быть быстрым, а не размашистым."],[100,"100м откуп спокойно"],[100,"4х25м ноги с доской в полную силу, режим 1:00","С доской видно, куда уходит усилие. Если доска прыгает и вы плывёте медленно — работа идёт вверх-вниз, а не назад."]],cool:[[100,"100м спина спокойно"],[100,"100м кроль с колобашкой, ноги отдыхают"],[100,"100м произвольно"]]},
      {n:3,vol:2100,note:"Колобашка выключает ноги — и вся скорость остаётся на плечах и предплечьях",story:"Колобашка выключает ноги — и вся скорость остаётся на плечах и предплечьях. Это самый быстрый способ понять, сколько на самом деле даёт ваш гребок. Плюс в спринте руки устают первыми, так что тренировать их отдельно имеет прямой смысл.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м руки с колобашкой спокойно"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i20: первые два на кулаках, вторые два руки с колобашкой в прогресс — настраиваем захват, без максимума"]],main:[[200,"8х25м руки с колобашкой в полную силу, режим 1:15","Без ног таз проваливается. Держите его у поверхности напряжением живота: если тело складывается, гребок начинает толкать воду вниз, а не назад."],[200,"200м откуп: 100м спина + 100м кроль спокойно"],[200,"4х50м руки с колобашкой и мал лоп, режим 1:45: 25м максимум + 25м свободно","С лопатками легко протащить воду прямой рукой. Следите за высоким локтем: кисть всегда ниже локтя, иначе гребок держится на лопатке, а не на опоре."],[100,"100м откуп спокойно на спине"],[200,"4х50м руки с колобашкой без лопаток в полную силу, режим 1:45","Ради этой серии и надевались лопатки. Опора должна чувствоваться такой же — если без них рука проскальзывает, значит захват держался на инвентаре."],[100,"100м откуп спокойно"]],cool:[[200,"200м в трубке спокойно: 100м ноги брассом + 100м ноги кролем"],[100,"100м спина спокойно"],[100,"100м произвольно"]],safe:"Лопатки вместе с колобашкой нагружают плечо сильнее всего: ноги не поддерживают тело, вся работа лежит на плечевом суставе. При боли в плече серия плывётся без лопаток."},
      {n:4,vol:2100,note:"На дистанции скорость чаще всего теряется не на воде, а на стенке",story:"На дистанции скорость чаще всего теряется не на воде, а на стенке. Эта тренировка бьёт точно в этот момент: сначала отдельно разбираем выход из поворота, потом заход в него, и только в конце собираем всё вместе. В 25-метровом бассейне поворотов очень много, поэтому и выигрыш здесь самый большой.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i20: подход к стенке спокойно и поворот без ускорения — отрабатываем сам разворот"]],main:[[300,"6х50м кроль, режим 1:30: первые 25м спокойно, вторые 25м в полную силу. Работаем выход из поворота","Скорость второй половины закладывается до стенки. Не «доплывайте» до бортика: последний гребок остаётся полным, группировка начинается близко к стенке."],[100,"100м откуп спокойно на спине"],[300,"6х50м кроль, режим 1:30: первые 25м в полную силу, вторые 25м спокойно. Работаем заход в стенку","Самая частая ошибка — сбросить скорость перед поворотом, чтобы «удобно» развернуться. Заходите на полном ходу, стопы ставьте на глубине 30–40 см."],[100,"100м откуп спокойно"],[200,"4х50м кроль в полную силу, режим 2:00","Здесь обе половины собираются вместе. Сравните время с первыми двумя сериями: если пятидесятка медленнее, чем сумма быстрых половин, скорость теряется именно на стенке."]],cool:[[100,"100м скольжений: толчок от бортика и скольжение до полной остановки, остаток отрезка спокойно (4х25м)"],[200,"200м спина спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:5,vol:1900,note:"Старт — единственный момент заплыва, когда пловец движется быстрее, чем способен плыть",story:"Старт — единственный момент заплыва, когда пловец движется быстрее, чем способен плыть. Эта тренировка про то, чтобы не растерять скорость в первые секунды. Отрезки короткие, отдых полный, и обязательный замер пятнадцати метров: без цифры прогресс здесь не виден.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i30: со старта спокойно — отрабатываем вход в воду и первые метры без максимума"]],main:[[300,"6х50м, режим 2:00: старт + 15м максимум с замером времени + 35м свободно","Время пятнадцати метров зависит не от силы толчка, а от чистоты входа. Брызг почти не должно быть: если тело шлёпнуло по воде, дальше уже неважно, как сильно вы оттолкнулись."],[200,"200м откуп спокойно на спине"],[150,"6х25м со старта в полную силу, режим 2:00","Первый гребок начинается после выхода на поверхность, а не под водой. Гребок на всплытии гасит скорость подводной части."],[150,"150м откуп: 100м спина + 50м кроль"]],cool:[[100,"100м скольжений с бортика: толчок, длинное скольжение, остаток отрезка спокойно"],[200,"200м спина: работа двумя руками одновременно"],[100,"100м произвольно"]],safe:"Стартовые прыжки: глубина в зоне приводнения от 1,8 м, тумба и бортик сухие, зона приводнения свободна. Если техника прыжка ещё не поставлена, сначала пройдите поэтапное обучение стартовому прыжку, а серию плывите со старта из воды."},
      {n:6,vol:1950,note:"Скорость — это не только максимум, но и умение его набирать",story:"Скорость — это не только максимум, но и умение его набирать. Здесь каждый следующий отрезок быстрее предыдущего, и так четыре раза подряд, каждый раз новым стилем. Такая работа учит разгоняться управляемо, а не выпрыгивать с первого метра и потом доживать отрезок на морально-волевых.",warm:[[200,"200м комплекс по 50м, спокойно"],[200,"200м ноги комплекс без доски"],[200,"4х50м комплекс по 25м (дельфин / спина, затем брасс / кроль) в прогресс, i30"],[100,"4х25м i20: по одному отрезку каждым стилем в прогресс"]],main:[[550,"4 серии по 4х25м i30, каждая серия своим стилем — дельфин, спина, брасс, кроль: первый отрезок спокойно, второй средне, третий быстро, четвёртый максимум. Между сериями 50м откуп спокойно","Прогресс должен быть ровным: разница между ступенями примерно одинаковая. Если первый отрезок уже быстрый, расти некуда — начинайте спокойнее, чем кажется нужным."],[100,"100м откуп спокойно на спине"],[200,"4х50м основной стиль в полную силу, режим 2:00","После четырёх прогрессий тело уже знает, как включаться. Здесь ступеней нет — максимум с первого гребка."]],cool:[[200,"200м упражнения из курса: по 50м на каждый стиль"],[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:7,vol:2100,note:"На дистанции ускоряться приходится не там, где удобно, а там, где нужно: на входе в поворот…",story:"На дистанции ускоряться приходится не там, где удобно, а там, где нужно: на входе в поворот, в середине отрезка, на финише. Здесь максимальный участок каждый раз в новом месте пятидесятки — тело учится включаться из любого положения и с любой скорости.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской, i30"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i20: 15м спокойно + 10м ускорение"]],main:[[200,"4х50м кроль, режим 1:30: 15м максимально + 35м свободно","Ускорение с места: тело ещё не разогналось, поэтому важна частота, а не размах. Считайте, за сколько гребков проходите первые 15 метров."],[100,"100м откуп спокойно на спине"],[200,"4х50м кроль, режим 1:30: 15м свободно + 20м максимально + 15м свободно","Ускорение с хода — самое трудное: скорость уже есть, и добавлять приходится поверх неё. Включение должно быть мгновенным, а не постепенным."],[100,"100м откуп спокойно на спине"],[200,"4х50м кроль, режим 1:30: 35м свободно + 15м максимально на финиш","Финишный участок плывётся на уставших руках. Не поднимайте голову перед стенкой — это главная потеря времени на финише."],[200,"200м откуп: 100м спина + 100м кроль"]],cool:[[200,"200м спина: 50м двумя руками одновременно + 50м обычно, дважды"],[100,"100м в трубке ноги кролем спокойно"],[100,"100м произвольно"]]},
      {n:8,vol:2250,note:"Самое трудное в спринте — не разогнаться, а переключиться",story:"Самое трудное в спринте — не разогнаться, а переключиться. Внутри одного отрезка темп меняется дважды: быстро, спокойно и снова быстро. Во второй серии добавляем связку дельфин плюс кроль — она встречается в комплексе и хорошо учит менять характер движения на ходу.",warm:[[300,"300м спокойно: 150м кроль + 100м спина + 50м дельфин"],[200,"200м ноги дельфином в ластах, i30"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i20: через одну — дельфин и кроль"]],main:[[450,"6х75м кроль i45: 25м быстро / 25м спокойно / 25м быстро","Спокойный участок — не отдых, а удержание положения. Тело остаётся высоко, гребок длинный; если провалились, второе ускорение уже не получится."],[200,"200м откуп спокойно на спине"],[300,"6х50м i45: 25м дельфин в полную силу, затем 25м кроль спокойно","После дельфина тело хочет продолжать волну — переключение на кроль должно быть немедленным, с первого гребка. Это ровно то, что нужно на переходе в комплексе."],[100,"100м откуп спокойно"]],cool:[[150,"150м спина спокойно"],[150,"150м упражнения из курса на кроль"],[100,"100м кроль на минимальное число гребков"]]},
      {n:9,vol:2100,note:"На спринте дыхание — всегда лишнее движение: голова поворачивается, тело тормозит",story:"На спринте дыхание — всегда лишнее движение: голова поворачивается, тело тормозит. Здесь мы сокращаем число вдохов и учимся держать голову на максимальной скорости. Это не задержка дыхания на пределе, а именно сокращённое дыхание на коротких отрезках — разница принципиальная.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской"],[200,"4х50м кроль i30, дыхание на 3 гребка"],[100,"4х25м кроль i20 в прогресс, один вдох на отрезке"]],main:[[200,"8х25м кроль в полную силу, один вдох на отрезке, режим 1:15","Вдох делается в первой половине отрезка, а не перед стенкой. Вдох на последних метрах поднимает голову ровно там, где нужна максимальная скорость."],[200,"200м откуп: 100м спина + 100м кроль спокойно"],[300,"6х50м кроль, режим 1:45: 25м максимум с дыханием на 5 гребков + 25м свободно","Одно очко остаётся в воде на каждом вдохе. Если голова поднимается, ноги проваливаются — и экономия на вдохах уходит в потерю положения."],[200,"200м откуп спокойно на спине"]],cool:[[200,"200м спина спокойно, дыхание полностью свободное"],[200,"200м в трубке: 100м ноги брассом + 100м ноги кролем"],[100,"100м произвольно"]],safe:"Не гипервентилировать перед отрезками. Не задерживать дыхание до предела и не выполнять эту работу в одиночку. При головокружении, потемнении в глазах или любом дискомфорте — прекратить серию и перейти к спокойному плаванию."},
      {n:10,vol:2250,note:"Заплывы выигрываются на последних метрах, а тренируют их реже всего: обычно к концу серии сил…",story:"Заплывы выигрываются на последних метрах, а тренируют их реже всего: обычно к концу серии сил уже нет и финиш плывётся кое-как. Здесь всё построено наоборот — каждый отрезок заканчивается максимальным участком, и стенка всегда касается на полном ходу.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i20: последние 10м каждого отрезка — ускорение"]],main:[[450,"6х75м кроль i40: 50м средний темп + 25м максимум на финиш","Максимум начинается ровно на отметке, а не «когда получится». Заранее решите, где включаетесь, и держите это решение на всех шести отрезках."],[200,"200м откуп спокойно на спине"],[300,"6х50м, режим 1:45: 35м спокойно + 15м максимально быстро на финиш","На последних метрах гребок укорачивается сам. Сознательно доводите руку до бедра: короткий частый гребок на финише почти не двигает вперёд."],[100,"100м откуп спокойно"],[100,"4х25м основной стиль в полную силу до касания стенки, режим 1:30","Касание — часть отрезка. Не поднимайте голову и не подглядывайте на стенку: последний гребок должен быть таким же полным, как первый."]],cool:[[200,"200м спина: работа двумя руками одновременно"],[100,"100м скольжений с бортика"],[100,"100м произвольно"]]},
      {n:11,vol:2100,note:"Скорость складывается из мощности и умения её приложить",story:"Скорость складывается из мощности и умения её приложить. Сначала мы перегружаем гребок чашечками, а сразу после снимаем их — и тело какое-то время движется непривычно легко. Именно в этот момент и запоминается ощущение быстрого плавания, ради него всё и делается.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м кроль с мал лоп i30 в прогресс"]],main:[[200,"8х25м кроль с чашечками в полную силу, режим 2:00","С чашечками легко начать частить впустую. Гребок должен оставаться длинным: лучше меньше гребков с полной опорой, чем много коротких и суетливых."],[200,"200м откуп спокойно на спине"],[200,"4х50м кроль с чашечками в полную силу, режим 2:00","Сопротивление подчёркивает провал локтя. Держите кисть ниже локтя — с чашечками это чувствуется отчётливее, чем без них."],[200,"200м откуп: 100м спина + 100м кроль"],[200,"4х50м кроль без чашечек в полную силу, режим 2:00","Запомните ощущение лёгкости и постарайтесь удержать ту же длину гребка. Ради этих четырёх отрезков и делалось всё предыдущее."]],cool:[[100,"100м кроль на минимальное число гребков — ловим ощущение свободного продвижения"],[200,"200м спина спокойно"],[100,"100м упражнения из курса на кроль"]]},
      {n:12,vol:2200,note:"Чтобы плыть быстро, нервная система должна знать, что такое быстро",story:"Чтобы плыть быстро, нервная система должна знать, что такое быстро. Ласты дают скорость выше собственной, и тело успевает запомнить частоту гребка и положение на этой скорости. Дальше задача простая и сложная одновременно: воспроизвести то же ощущение уже без ласт.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги в ластах спокойно"],[200,"4х50м в ластах в прогресс, i30"],[100,"4х25м в ластах i20: через одну — дельфин и кроль"]],main:[[200,"8х25м кроль в ластах в полную силу с высокой частотой гребка, режим 1:15","Ласты дают скорость, а ваша задача — частота рук. Не позволяйте ластам везти вас: руки должны работать чаще обычного."],[200,"200м откуп спокойно на спине"],[300,"6х50м, режим 1:45: 25м в ластах максимум + 25м свободно","Обратите внимание на положение тела на высокой скорости: таз выше, тело ровнее. Это и есть образец, к которому нужно вернуться без ласт."],[100,"100м откуп спокойно"],[200,"4х50м кроль без ласт в полную силу, режим 2:00","Повторить ту же частоту гребка, что была в ластах. Скорость будет ниже — это нормально, важно ощущение темпа."],[100,"100м откуп спокойно"]],cool:[[200,"200м спина: работа двумя руками одновременно"],[100,"100м кроль с колобашкой спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:13,vol:2200,note:"Скорость — это частота гребка, умноженная на его длину",story:"Скорость — это частота гребка, умноженная на его длину. Обычно пловец улучшает одно за счёт другого и стоит на месте. Здесь мы разводим эти два параметра и смотрим, где именно ваш личный резерв: на каждом отрезке считаем и гребки, и время.",warm:[[200,"200м спокойно: 100м кроль с подсчётом гребков + 100м спина"],[200,"200м ноги с доской"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м кроль i20 на минимальное число гребков"]],main:[[200,"4х50м кроль в полную силу, записать время и число гребков, режим 2:00","Это ваша исходная точка. Записывайте оба числа — дальше вся тренировка строится вокруг них."],[200,"4х50м кроль: то же время, но на 2 гребка меньше, режим 2:00","Работаем над длиной гребка. Помогает более длинное вытягивание вперёд после входа руки и доведение гребка до бедра."],[200,"4х50м кроль: то же число гребков, но быстрее, режим 2:00","Работаем над частотой при сохранении длины. Ускоряться нужно не входом руки, а окончанием гребка."],[200,"200м откуп: 100м спина + 100м кроль"],[150,"6х25м кроль в полную силу с максимальной частотой, режим 1:15","Здесь длину не считаем — только частоту. Сравните ощущение с предыдущими сериями: где скорость выше, там и ваш резерв."],[150,"150м откуп спокойно"]],cool:[[200,"4х50м кроль на минимальное число гребков, i20"],[100,"100м спина спокойно"],[100,"100м в трубке ноги кролем"]]},
      {n:14,vol:2300,note:"В комплексе секунды теряются не в стилях, а на стыках между ними",story:"В комплексе секунды теряются не в стилях, а на стыках между ними. Переход с дельфина на спину и со спины на брасс — два места, где любители теряют больше всего и где почти никто не тренируется отдельно. Здесь мы разгоняем стиль до максимума именно перед сменой, чтобы переход приходилось делать на скорости.",warm:[[200,"200м комплекс по 50м, спокойно"],[200,"200м ноги комплекс без доски"],[200,"4х50м i30: 25м спина + 25м брасс"],[100,"4х25м i20: по одному отрезку каждым стилем"]],main:[[300,"6х50м, режим 1:45: 25м дельфин в полную силу, затем 25м спина спокойно. Работаем сам переход","На касании обе руки приходят одновременно. Разворот на спину начинается сразу с касания, без паузы и без лишнего гребка под водой."],[100,"100м откуп спокойно"],[300,"6х50м, режим 1:45: 25м спина в полную силу, затем 25м брасс спокойно. Работаем сам переход","Здесь легче всего получить дисквалификацию: до касания стенки нужно оставаться на спине. Уход с плеча раньше касания — прямое нарушение правил."],[100,"100м откуп спокойно"],[400,"4х100м комплекс i45","Соберите оба перехода в цельный отрезок. Скорость не главное — важно, чтобы на стыках не появлялось паузы."]],cool:[[200,"200м упражнения из курса: 100м на спину + 100м на брасс"],[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:15,vol:2200,note:"Финальная тренировка блока — про самый неудобный переход в комплексе и про контроль",story:"Финальная тренировка блока — про самый неудобный переход в комплексе и про контроль. Брасс уводит тело вниз, кроль требует высокого положения, и между ними всего одно касание. В конце два стометровых комплекса на время: это ваш замер, к которому вы вернётесь через месяц.",warm:[[200,"200м комплекс по 50м, спокойно"],[200,"200м ноги комплекс без доски"],[200,"4х50м кроль в прогресс, i30"],[100,"4х25м i20: по одному отрезку каждым стилем в прогресс"]],main:[[300,"6х50м, режим 1:45: 25м брасс в полную силу, затем 25м кроль в полную силу. Переход выполняется без паузы","После брасса тело идёт низко. Первые метры кроля плывутся с акцентом на ноги, иначе таз останется внизу и скорость не вернётся."],[200,"200м откуп спокойно на спине"],[200,"4х50м i45: 25м спина в полную силу, затем 25м брасс спокойно","Второй трудный переход. Касание на спине, затем разворот — и первый гребок брассом уже полный, а не пробный."],[100,"100м откуп спокойно"],[200,"2х100м комплекс на время, i2:00","Плывите как на соревнованиях и записывайте время. Это контрольная точка блока — через месяц повторите её в тех же условиях."],[100,"100м откуп спокойно"]],cool:[[200,"200м спина спокойно: в каждом полтиннике 25м двумя руками одновременно + 25м обычно"],[100,"100м скольжений с бортика"],[100,"100м кроль на минимальное число гребков"]]}
    ]},
    sk_p:{level:"Продвинутый",vol:"2200–3000 м",w:[
      {n:1,vol:2400,note:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость",story:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость. Первая половина кролем, вторая — своим стилем, потому что скорость нужна не только в кроле. Задача не терпеть, а каждый раз стартовать свежим: если время падает к концу серии, не хватило отдыха, а не характера.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[null,"8х25м i20: нечётные — упражнение на координацию, чётные — плавание в прогресс"],[null,"4х50м в ластах: 25м в прогресс + 25м свободно, режим 1:30"],[null,"8х25м ноги в ластах, максимальная частота, режим 1:00"]],main:[[null,"8х25м кроль в полную силу, режим 1:30. Стараемся дышать реже обычного","Считайте гребки. К концу серии их число не должно вырасти больше чем на один-два: если выросло, скорость держится частотой, а гребок уже разваливается."],[null,"300м откуп: 200м спина спокойно + 100м кроль на минимальное число гребков"],[null,"4х50м основной стиль в полную силу, режим 2:00","На своём стиле техника рассыпается первой. Следите за длиной гребка, а не за частотой: на дистанции выигрывает тот, кто на скорости остаётся техничным."],[null,"200м откуп: 100м спина + 100м кроль спокойно"],[null,"4х50м кроль, режим 1:30: 25м максимум + 25м свободно","Вторая половина — не выключение, а спокойное продолжение. Тело остаётся вытянутым, гребок длинным: учимся сбрасывать усилие, не теряя положения."]],cool:[[null,"100м спина спокойно"],[null,"4х50м кроль на минимальное число гребков, i20 — не разгоняясь, только за счёт длины"],[null,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:2200,note:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго",story:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго. Здесь наоборот: короткие максимальные отрезки, предельная частота и разные положения тела. После такой тренировки обычный кроль ощущается легче, потому что ноги перестают быть тормозом и начинают толкать.",warm:[[null,"300м спокойно: 150м кроль + 150м спина"],[null,"200м ноги с доской спокойно: 100м кроль + 100м брасс"],[null,"4х50м ноги в ластах в прогресс, i30"],[null,"4х25м ноги дельфином на спине в ластах, i20"]],main:[[null,"12х25м ноги кролем без доски в полную силу, режим 1:15","Колени не выходят из воды, движение идёт от бедра. На максимальной частоте это теряется первым — как только на поверхности появились колени, отдохните лишние 15 секунд."],[null,"200м откуп: 100м спина спокойно + 100м кроль"],[null,"6х50м ноги, режим 1:30: 25м дельфином на груди максимум + 25м на спине свободно","Дельфин на максимуме идёт от груди и таза, а не от коленей. Стопы вместе, амплитуда небольшая — так удар получается быстрым, а не размашистым."],[null,"200м откуп: спокойно на спине"]],cool:[[null,"200м спина: работа двумя руками одновременно, ноги почти без усилия"],[null,"100м кроль с колобашкой, ноги отдыхают"],[null,"100м произвольно спокойно"]]},
      {n:3,vol:2600,note:"Колобашка выключает ноги — и вся скорость остаётся на плечах и предплечьях",story:"Колобашка выключает ноги — и вся скорость остаётся на плечах и предплечьях. Это самый быстрый способ понять, сколько на самом деле даёт ваш гребок. Плюс в спринте руки устают первыми, так что тренировать их отдельно имеет прямой смысл.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м координация"],[null,"200м руки с колобашкой спокойно"],[null,"4х50м кроль в прогресс, i30"],[null,"4х25м i20: первые два на кулаках, вторые два руки с колобашкой в прогресс — настраиваем захват, без максимума"]],main:[[null,"12х25м руки с колобашкой в полную силу, режим 1:15","Без ног таз проваливается. Держите его у поверхности напряжением живота — если тело складывается, гребок начинает толкать воду вниз, а не назад."],[null,"300м откуп: 200м спина + 100м кроль спокойно"],[null,"4х50м руки с колобашкой и средними лопатками, режим 1:45: 25м максимум + 25м свободно","Средние лопатки заметно увеличивают нагрузку на плечо, поэтому техника здесь важнее усилия. Следите за высоким локтем: кисть всегда ниже локтя, иначе гребок держится на лопатке, а не на опоре."],[null,"200м откуп: спокойно на спине"],[null,"4х50м руки с колобашкой без лопаток в полную силу, режим 1:45","Ради этой серии и надевались лопатки. Опора должна чувствоваться такой же — если без лопаток рука проскальзывает, значит захват держался на инвентаре."],[null,"200м откуп: 100м спина + 100м кроль"]],cool:[[null,"200м в трубке спокойно: 100м ноги брассом + 100м ноги кролем"],[null,"100м спина спокойно"],[null,"100м произвольно"]],safe:"Средние лопатки вместе с колобашкой нагружают плечо максимально: ноги не поддерживают тело, вся работа лежит на плечевом суставе. Объём такой работы — не больше 200–300 м за тренировку. При боли в плече серия плывётся с маленькими лопатками или без них."},
      {n:4,vol:2500,note:"На дистанции скорость чаще всего теряется не на воде, а на стенке",story:"На дистанции скорость чаще всего теряется не на воде, а на стенке. Эта тренировка бьёт точно в этот момент: каждый отрезок содержит поворот и максимальные метры вокруг него. Кто научился проходить стенку в полную силу, получает бесплатные десятые на каждом повороте — а в 25-метровом бассейне их очень много.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[null,"200м ноги дельфином на спине в ластах, i30"],[null,"4х50м кроль в прогресс, i30"],[null,"8х25м i20: подход к стенке спокойно и поворот без ускорения — отрабатываем сам разворот"]],main:[[null,"6х50м кроль, режим 1:30: первые 25м спокойно, вторые 25м в полную силу. Работаем выход из поворота","Скорость второй половины закладывается до стенки. Не «доплывайте» до бортика: последний гребок остаётся полным, группировка начинается близко к стенке."],[null,"200м откуп: спокойно на спине"],[null,"6х50м кроль, режим 1:30: первые 25м в полную силу, вторые 25м спокойно. Работаем заход в стенку","Самая частая ошибка — сбросить скорость перед поворотом, чтобы «удобно» развернуться. Заходите на полном ходу, стопы ставьте на глубине 30–40 см."],[null,"200м откуп: 100м спина + 100м кроль"],[null,"4х50м кроль в полную силу, режим 2:00","Здесь обе половины собираются вместе. Сравните время с первыми двумя сериями: если пятидесятка медленнее, чем сумма быстрых половин, скорость теряется именно на стенке."]],cool:[[null,"100м скольжений: толчок от бортика и скольжение до полной остановки, остаток отрезка доплываем спокойно (4х25м)"],[null,"200м спина спокойно"],[null,"100м кроль на минимальное число гребков"]]},
      {n:5,vol:2300,note:"Старт — единственный момент заплыва, когда пловец движется быстрее, чем способен плыть",story:"Старт — единственный момент заплыва, когда пловец движется быстрее, чем способен плыть. Эта тренировка про то, чтобы не растерять скорость в первые секунды. Отрезки короткие, отдых полный, и обязательный замер пятнадцати метров: без цифры прогресс здесь не виден.",warm:[[null,"300м спокойно: 150м кроль + 150м спина"],[null,"200м ноги с доской"],[null,"4х50м кроль в прогресс, i30"],[null,"8х25м i30: со старта спокойно — отрабатываем вход в воду и первые метры без максимума"]],main:[[null,"6х50м, режим 2:00: старт + 15м максимум с замером времени + 35м свободно","Время пятнадцати метров зависит не от силы толчка, а от чистоты входа. Брызг почти не должно быть — если тело шлёпнуло, дальше уже неважно, как сильно вы оттолкнулись."],[null,"200м откуп: спокойно на спине"],[null,"8х25м со старта в полную силу, режим 2:00","Первый гребок начинается после выхода на поверхность, а не под водой. Гребок под водой на всплытии гасит скорость подводной части."],[null,"300м откуп: 150м спина + 150м кроль спокойно"]],cool:[[null,"100м скольжений с бортика: толчок, длинное скольжение, остаток отрезка спокойно"],[null,"200м спина: работа двумя руками одновременно"],[null,"100м произвольно"]],safe:"Стартовые прыжки: глубина в зоне приводнения от 1,8 м, тумба и бортик сухие, зона приводнения свободна. При травмах шеи и спины серия со старта заменяется на старт из воды."},
      {n:6,vol:2500,note:"Скорость — это не только максимум, но и умение его набирать",story:"Скорость — это не только максимум, но и умение его набирать. Здесь каждый следующий отрезок быстрее предыдущего, и так четыре раза подряд, каждый раз новым стилем. Такая работа учит разгоняться управляемо, а не выпрыгивать с первого метра и потом доживать отрезок на морально-волевых.",warm:[[null,"400м комплекс по 100м, спокойно"],[null,"200м ноги комплекс без доски, i30"],[null,"4х50м комплекс по 25м (дельфин / спина, затем брасс / кроль) в прогресс, i30"],[null,"4х25м i20: по одному отрезку каждым стилем в прогресс"]],main:[[null,"4 серии по 4х50м i45, каждая серия своим стилем — дельфин, спина, брасс, кроль: 1-я спокойно, 2-я средне, 3-я быстро, 4-я максимум. Между сериями 100м откуп спокойно на спине","Прогресс должен быть ровным: разница между ступенями примерно одинаковая. Если первая уже быстрая, расти некуда — начинайте спокойнее, чем кажется нужным."],[null,"4х25м основной стиль в полную силу, режим 1:30","После четырёх стилей своим плыть тяжелее обычного — именно в этом смысл. Техника не должна отличаться от свежего состояния."]],cool:[[null,"200м упражнения из курса: по 50м на каждый стиль"],[null,"100м спина спокойно"],[null,"100м кроль на минимальное число гребков"]]},
      {n:7,vol:2400,note:"На дистанции ускоряться приходится не там, где удобно, а там, где нужно: на входе в поворот…",story:"На дистанции ускоряться приходится не там, где удобно, а там, где нужно: на входе в поворот, в середине отрезка, на финише. Здесь максимальный участок каждый раз в новом месте пятидесятки — тело учится включаться из любого положения и с любой скорости.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м координация"],[null,"200м ноги с доской, i30"],[null,"4х50м кроль в прогресс, i30"],[null,"8х25м i20: 15м спокойно + 10м ускорение"]],main:[[null,"4х50м кроль, режим 1:30: 15м максимально + 35м свободно","Ускорение с места: тело ещё не разогналось, поэтому важна частота, а не размах. Считайте, за сколько гребков проходите первые 15 метров."],[null,"100м откуп спокойно на спине"],[null,"4х50м кроль, режим 1:30: 15м свободно + 20м максимально + 15м свободно","Ускорение с хода — самое трудное: скорость уже есть, и добавлять приходится поверх неё. Включение должно быть мгновенным, а не постепенным."],[null,"100м откуп спокойно на спине"],[null,"4х50м кроль, режим 1:30: 35м свободно + 15м максимально на финиш","Финишный участок плывётся на уставших руках. Не поднимайте голову перед стенкой — это главная потеря времени на финише."],[null,"300м откуп: 150м спина + 150м кроль"]],cool:[[null,"200м спина: 50м двумя руками одновременно + 50м обычно, дважды"],[null,"100м в трубке ноги кролем спокойно"],[null,"100м произвольно"]]},
      {n:8,vol:2600,note:"Самое трудное в спринте — не разогнаться, а переключиться",story:"Самое трудное в спринте — не разогнаться, а переключиться. Внутри одного отрезка темп меняется дважды: быстро, спокойно и снова быстро. Во второй серии добавляем связку дельфин плюс кроль — она встречается и в комплексе, и просто хорошо учит менять характер движения на ходу.",warm:[[null,"400м спокойно: 200м кроль + 100м спина + 100м дельфин"],[null,"200м ноги дельфином в ластах, i30"],[null,"4х50м кроль в прогресс, i30"],[null,"8х25м i20: через одну — дельфин и кроль"]],main:[[null,"8х75м кроль i45: 25м быстро / 25м спокойно / 25м быстро","Спокойный участок — не отдых, а удержание положения. Тело остаётся высоко, гребок длинный; если провалились, второе ускорение уже не получится."],[null,"200м откуп спокойно на спине"],[null,"8х50м i45: 25м дельфин в полную силу + 25м кроль спокойно","После дельфина тело хочет продолжать волну — переключение на кроль должно быть немедленным, с первого гребка. Это ровно то, что нужно на переходе в комплексе."]],cool:[[null,"150м спина спокойно"],[null,"150м упражнения из курса на кроль"],[null,"100м кроль на минимальное число гребков"]]},
      {n:9,vol:2400,note:"На спринте дыхание — всегда лишнее движение: голова поворачивается, тело тормозит",story:"На спринте дыхание — всегда лишнее движение: голова поворачивается, тело тормозит. Здесь мы сокращаем число вдохов и учимся держать голову на максимальной скорости. Это не задержка дыхания на пределе, а именно сокращённое дыхание на коротких отрезках — разница принципиальная.",warm:[[null,"300м спокойно: 150м кроль + 150м спина"],[null,"200м ноги с доской, i30"],[null,"4х50м кроль i30, дыхание на 3 гребка"],[null,"2 серии по 4х25м кроль i20 в прогресс: внутри каждой четвёрки от спокойного к максимуму, один вдох на отрезке"]],main:[[null,"8х25м кроль в полную силу, один вдох на отрезке, режим 1:30","Вдох делается в первой половине отрезка, а не перед стенкой. Вдох на последних метрах поднимает голову ровно там, где нужна максимальная скорость."],[null,"300м откуп: 200м спина + 100м кроль спокойно"],[null,"6х50м кроль, режим 1:45: 25м максимум с дыханием на 5 гребков + 25м свободно","Одно очко остаётся в воде на каждом вдохе. Если голова поднимается, ноги проваливаются — и экономия на вдохах уходит в потерю положения."],[null,"200м откуп спокойно на спине"]],cool:[[null,"200м спина спокойно, дыхание полностью свободное"],[null,"200м в трубке: 100м ноги брассом + 100м ноги кролем"],[null,"100м произвольно"]],safe:"Не гипервентилировать перед отрезками. Не задерживать дыхание до предела и не выполнять эту работу в одиночку. При головокружении, потемнении в глазах или любом дискомфорте — прекратить серию и перейти к спокойному плаванию."},
      {n:10,vol:3000,note:"Заплывы выигрываются на последних метрах, а тренируют их реже всего",story:"Заплывы выигрываются на последних метрах, а тренируют их реже всего. Здесь каждая серия заканчивается максимальным финишным отрезком, причём на фоне накопленной усталости — ровно как это происходит на дистанции. Финиш плывём и кролем, и своим стилем.",warm:[[null,"400м спокойно: по 100м каждым стилем"],[null,"200м ноги в ластах"],[null,"4х50м кроль в прогресс, i30"],[null,"8х25м i20: последние 10м каждого отрезка — ускорение"]],main:[[null,"6х100м кроль i40: 75м средний темп + 25м максимум на финиш","Средний темп — это темп вашей дистанции, а не прогулка. Финишная двадцатипятка должна получаться за счёт переключения, а не потому что до этого вы плыли медленно."],[null,"200м откуп спокойно на спине"],[null,"6х50м основной стиль, режим 1:30: 35м спокойно + 15м максимально быстро на финиш","На своём стиле следите за техникой финиша: в брассе и дельфине касание двумя руками, в кроле и спине — не поднимать голову перед стенкой."],[null,"100м откуп спокойно"],[null,"4х50м кроль, режим 1:30: 25м средний темп + 25м максимум на финиш","Здесь максимальный участок вдвое длиннее. Задача — дотерпеть его до стенки, не сбросив на последних метрах."],[null,"200м откуп: 100м спина + 100м кроль спокойно"]],cool:[[null,"200м спина: работа двумя руками одновременно, следим за длинным гребком"],[null,"100м скольжений с бортика: толчок и скольжение до остановки, остаток спокойно"],[null,"100м произвольно"]]},
      {n:11,vol:2400,note:"Скорость складывается из мощности и умения её приложить",story:"Скорость складывается из мощности и умения её приложить. Сначала мы перегружаем гребок чашечками, а сразу после снимаем их — и тело какое-то время движется непривычно легко. Именно в этот момент и запоминается ощущение быстрого плавания, ради него всё и делается.",warm:[[null,"300м спокойно: 150м кроль + 150м спина"],[null,"200м ноги с доской"],[null,"4х50м кроль в прогресс, i30"],[null,"2 серии по 4х25м кроль с мал лоп i30 в прогресс: внутри каждой четвёрки от спокойного к максимуму"]],main:[[null,"8х25м кроль с чашечками в полную силу, режим 2:00","С чашечками легко начать частить впустую. Гребок должен оставаться длинным: лучше меньше гребков с полной опорой, чем много коротких и суетливых."],[null,"200м откуп спокойно на спине"],[null,"6х50м кроль с чашечками в полную силу, режим 2:00","Сопротивление подчёркивает провал локтя. Держите кисть ниже локтя — с чашечками это чувствуется отчётливее, чем без них."],[null,"200м откуп: 100м спина + 100м кроль"],[null,"4х50м кроль без чашечек в полную силу, режим 2:00","Запомните ощущение лёгкости и постарайтесь удержать ту же длину гребка. Ради этих четырёх отрезков и делалось всё предыдущее."]],cool:[[null,"100м кроль на минимальное число гребков — ловим ощущение свободного продвижения без сопротивления"],[null,"200м спина спокойно"],[null,"100м упражнения из курса на кроль"]]},
      {n:12,vol:2600,note:"Чтобы плыть быстро, нервная система должна знать, что такое быстро",story:"Чтобы плыть быстро, нервная система должна знать, что такое быстро. Ласты дают скорость выше собственной, и тело успевает запомнить частоту гребка и положение на этой скорости. Дальше задача простая и сложная одновременно: воспроизвести то же ощущение уже без ласт.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м дельфин"],[null,"200м ноги в ластах спокойно"],[null,"4х50м в ластах в прогресс, i30"],[null,"8х25м в ластах i20: через одну — дельфин и кроль"]],main:[[null,"8х25м кроль в ластах в полную силу с высокой частотой гребка, режим 1:15","Ласты дают скорость, а ваша задача — частота рук. Не позволяйте ластам везти вас: руки должны работать чаще обычного."],[null,"200м откуп спокойно на спине"],[null,"6х50м, режим 1:45: 25м в ластах максимум + 25м свободно","Обратите внимание на положение тела на высокой скорости: таз выше, тело ровнее. Это и есть образец, к которому нужно вернуться без ласт."],[null,"200м откуп: 100м спина + 100м кроль"],[null,"6х50м кроль без ластов в полную силу, режим 2:00","Повторить ту же частоту гребка, что была в ластах. Скорость будет ниже — это нормально, важно ощущение темпа."],[null,"100м откуп спокойно"]],cool:[[null,"200м спина: работа двумя руками одновременно"],[null,"100м кроль с колобашкой спокойно"],[null,"100м произвольно, дыхание свободное"]]},
      {n:13,vol:2700,note:"Скорость — это частота гребка, умноженная на его длину",story:"Скорость — это частота гребка, умноженная на его длину. Обычно пловец улучшает одно за счёт другого и стоит на месте. Здесь мы разводим эти два параметра и смотрим, где именно ваш личный резерв: на каждом отрезке считаем и гребки, и время.",warm:[[null,"300м спокойно: 150м кроль с подсчётом гребков + 150м спина"],[null,"200м ноги с доской"],[null,"4х50м кроль в прогресс, i30"],[null,"8х25м кроль i20 на минимальное число гребков"]],main:[[null,"4х50м кроль в полную силу, записать время и число гребков, режим 2:00","Это ваша исходная точка. Записывайте оба числа — дальше вся тренировка строится вокруг них."],[null,"4х50м кроль: то же время, но на 2 гребка меньше, режим 2:00","Работаем над длиной гребка. Помогает более длинное вытягивание вперёд после входа руки и доведение гребка до бедра."],[null,"4х50м кроль: то же число гребков, но быстрее, режим 2:00","Работаем над частотой при сохранении длины. Ускоряться нужно не входом руки, а окончанием гребка."],[null,"300м откуп: 200м спина + 100м кроль"],[null,"8х25м кроль в полную силу с максимальной частотой, режим 1:15","Здесь длину не считаем — только частоту. Сравните ощущение с предыдущими сериями: где скорость выше, там и ваш резерв."],[null,"4 пары по 25м кроль i45: первый отрезок со средними лопатками в полную силу, второй — без лопаток в полную силу. Лопатки снимаем на бортике","Лопатки увеличивают шаг искусственно. Задача — на отрезке без них удержать то же число гребков: тело уже запомнило ощущение длинного гребка, остаётся воспроизвести его своей рукой."],[null,"100м откуп спокойно"]],cool:[[null,"4х50м кроль на минимальное число гребков, i20"],[null,"100м спина спокойно"],[null,"100м в трубке ноги кролем"]],safe:"Средние лопатки — не больше 200–300 м за тренировку и только при отсутствии боли в плече. Если гребок идёт с провалом локтя, лопатки закрепляют эту ошибку: сначала техника, потом инвентарь."},
      {n:14,vol:2600,note:"В комплексе секунды теряются не в стилях, а на стыках между ними",story:"В комплексе секунды теряются не в стилях, а на стыках между ними. Переход с дельфина на спину и со спины на брасс — два места, где любители теряют больше всего и где почти никто не тренируется отдельно. Здесь мы разгоняем стиль до максимума именно перед сменой, чтобы переход приходилось делать на скорости.",warm:[[null,"400м комплекс по 100м, спокойно"],[null,"200м ноги комплекс без доски, i30"],[null,"4х50м i30: 25м дельфин + 25м спина"],[null,"4х50м i30: 25м спина + 25м брасс"]],main:[[null,"8х50м, режим 1:45: 25м дельфин в полную силу, затем 25м спина спокойно. Работаем сам переход","Касание двумя руками одновременно, и только после него разворот на спину. Разворот, начатый до касания, — дисквалификация на соревнованиях и потеря скорости на тренировке."],[null,"200м откуп спокойно на спине"],[null,"8х50м, режим 1:45: 25м спина в полную силу, затем 25м брасс спокойно. Работаем сам переход","Касание выполняется в положении на спине. На скорости тело само тянет перевернуться раньше — следите, чтобы плечи не ушли за вертикаль до касания."],[null,"200м откуп: 100м спина + 100м кроль"]],cool:[[null,"200м упражнения из курса: 100м на спину + 100м на брасс"],[null,"100м спина спокойно"],[null,"100м произвольно"]]},
      {n:15,vol:2400,note:"Раз в месяц скорость нужно измерять, а не ощущать",story:"Раз в месяц скорость нужно измерять, а не ощущать. Сначала отрабатываем последний переход комплекса — с брасса на кроль, а потом делаем два замера сотни комплексом на время. Записывайте результаты: через месяц по ним будет видно, работает программа или вы просто плаваете.",warm:[[null,"400м спокойно: по 100м каждым стилем"],[null,"200м ноги комплекс без доски"],[null,"4х50м i30: 25м брасс + 25м кроль"],[null,"2 серии по 4х25м i20 в прогресс: в каждой четвёрке по отрезку на стиль — дельфин, спина, брасс, кроль"]],main:[[null,"8х50м, режим 1:45: 25м брасс в полную силу, затем 25м кроль в полную силу. Переход выполняется без паузы","Касание двумя руками, уход от стенки на груди. Это самый выгодный переход в комплексе: с брасса на кроль скорость растёт, и терять её на стенке особенно обидно."],[null,"300м откуп: 200м спина + 100м кроль спокойно"],[null,"2х100м комплекс в полную силу на время, отдых 5 минут","Записывайте время каждой сотни и разницу между ними. Вторая не должна быть медленнее первой больше чем на 2–3 секунды — иначе отдыха было мало."],[null,"100м откуп спокойно"]],cool:[[null,"200м спина спокойно: в каждом полтиннике 25м двумя руками одновременно + 25м обычно"],[null,"100м скольжений с бортика: толчок, скольжение до остановки, остаток спокойно"],[null,"100м кроль на минимальное число гребков"]]}
    ]}
  }},
  b_mo:{name:"Мощность",lede:"Длина гребка под нагрузкой. Судья здесь не секундомер, а число гребков.",levels:{
    mo_n:{level:"Новичок",vol:"1500 м",w:[
      {n:1,vol:1500,note:"Мощность — это не скорость",story:"Мощность — это не скорость. Как только пловец начинает грести изо всех сил, он почти всегда начинает рвать воду: рука проскальзывает, гребков становится больше, а вперёд вы двигаетесь хуже. Поэтому здесь мы плывём мощно и плавно, а главным показателем становится не время, а количество гребков на отрезок.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м в трубке спокойно, тело вытянуто в одну линию"],[100,"4х25м i20: упражнение «плавание на кулаках» — учимся опираться предплечьем"]],main:[[200,"8х25м ноги в ластах, i20, мощно и плавно","Работа идёт от бедра, стопа расслаблена. Колени из воды не показываются — если показались, вы бьёте коленом, а не толкаете бедром."],[100,"4х25м i20: упражнение «скайлинг» — ищем опору ладонью, почти без продвижения"],[200,"8х25м руки с колобашкой, i25, считаем гребки","Запишите число гребков на первом отрезке. Рост до трёх — нормально, больше — значит вы начали суетиться."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, с подсчётом гребков","На своём стиле длина гребка теряется первой. Лучше плыть медленнее, но длинно."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки: запишите лучшее число гребков на 25 м. Это ваша цифра, к ней будете возвращаться."]],cool:[[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:2,vol:1500,note:"Колобашка убирает ноги, и обмануть себя становится нечем: вперёд вас двигают только руки",story:"Колобашка убирает ноги, и обмануть себя становится нечем: вперёд вас двигают только руки. Для начинающего это лучший способ понять, что такое опора. Отрезки короткие, потому что руки устают быстро, а грести уставшими руками бессмысленно.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м руки с колобашкой спокойно, считаем гребки"],[100,"4х25м i20: упражнение «гребок только одной рукой», по два отрезка на руку"]],main:[[200,"8х25м ноги кролем с доской, i20 — считаем удары","Ноги работают от бедра, стопа вытянута. Число ударов на отрезке должно держаться одинаковым."],[100,"4х25м i20: упражнение «плавание на кулаках»"],[200,"8х25м руки с колобашкой, i25, мощно и плавно","Без ног таз проваливается. Держите его у поверхности напряжением живота, иначе гребок толкает воду вниз."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль с колобашкой, i30","Свой стиль без ног — непривычно. Если техника рассыпается, снимите колобашку и доплывите серию в координации."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Тело должно держаться так же высоко, как на колобашке, только теперь за счёт ног."]],cool:[[100,"100м в трубке ноги брассом спокойно"],[100,"100м спина спокойно"]]},
      {n:3,vol:1500,note:"Ноги дают опору всему телу: если таз провалился, даже сильный гребок будет тащить вас вверх…",story:"Ноги дают опору всему телу: если таз провалился, даже сильный гребок будет тащить вас вверх, а не вперёд. Здесь ноги — главный герой тренировки. Работаем ими так же, как руками: мощно, плавно и с подсчётом, чередуя ласты и работу без них.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской спокойно"],[100,"4х25м i20: упражнение «ноги кролем на боку», по два отрезка на каждый бок"]],main:[[200,"8х25м ноги в ластах, i20, мощно и плавно","Ласта должна прогибаться под давлением. Если она просто шлёпает по воде, движение идёт от колена."],[100,"4х25м i20: упражнение «ноги дельфин на спине» — движение от таза"],[200,"8х25м ноги с доской без ласт, i25, считаем удары","Без ласт число ударов растёт само собой. Задача обратная: удержать то же число и не частить."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, ноги активные","Здесь ноги проверяются на своём стиле. В брассе толчок идёт в стороны и назад, а не вниз."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. После ласт тело помнит высокое положение — постарайтесь удержать его своими ногами."]],cool:[[100,"100м кроль с колобашкой спокойно, ноги отдыхают"],[100,"100м спина спокойно"]]},
      {n:4,vol:1500,note:"Толчок от стенки — самое дешёвое место, где начинающий может выиграть время",story:"Толчок от стенки — самое дешёвое место, где начинающий может выиграть время. Хороший толчок несёт вас несколько метров бесплатно и снимает один-два гребка с каждого отрезка. Разбираем его отдельно: положение тела, глубину постановки стоп и скольжение.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м в трубке спокойно, тело вытянуто в одну линию"],[100,"4х25м i20: толчок от стенки и скольжение в стрелке до полной остановки, дальше спокойно"]],main:[[200,"8х25м i30: мощный толчок и скольжение в стрелке, дальше спокойно до бортика","Стопы на стенку ставятся на глубине 30–40 см, тело в стрелке до толчка. Голова между руками, одна кисть на другой."],[100,"4х25м i20: упражнение «скольжение на спине в стрелочке»"],[200,"8х25м кроль, i25, акцент на первые пять метров после стенки, считаем гребки","Первый гребок начинается после всплытия. Хороший толчок экономит один-два гребка на отрезке — это и есть его цена."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, с акцентом на выход от стенки","В брассе после толчка идёт длинный гребок под водой — не всплывайте раньше, чем скорость начнёт падать."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Отрезок начинается с толчка — считайте, сколько гребков нужно, чтобы дойти до стенки."]],cool:[[100,"100м скольжений с бортика: толчок, скольжение до остановки, дальше спокойно"],[100,"100м спина спокойно"]]},
      {n:5,vol:1500,note:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает",story:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает. Здесь мы разводим руки и смотрим на каждую отдельно. Разница между руками — это резерв, который не требует ни силы, ни объёма: достаточно подтянуть слабую сторону.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м упражнение «2 гребка правой, 2 гребка левой»"],[100,"4х25м i20: «один гребок правой, один левой, один двумя руками»"]],main:[[200,"8х25м ноги на боку с вытянутой рукой, i25 — по четыре отрезка на каждый бок","На боку сразу видно, какая сторона держит тело хуже. Плечо вытянутой руки прижато к уху, взгляд вниз."],[100,"4х25м i20: упражнение «гребок только одной рукой», вторая у бедра"],[200,"8х25м кроль одной рукой с колобашкой, i30: по отрезку на руку","Считайте гребки отдельно для правой и левой. Разница больше двух — слабую руку нужно грузить дополнительно."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30","На симметричных стилях перекос виден по траектории: тело уводит в сторону из-за более короткого гребка одной рукой."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Обратите внимание, с какой стороны вы дышите — чаще всего именно эта рука короче."]],cool:[[100,"100м спина: работа двумя руками одновременно"],[100,"100м произвольно"]]},
      {n:6,vol:1500,note:"Захват — самая недооценённая часть гребка",story:"Захват — самая недооценённая часть гребка. Большинство начинающих тянет слишком рано, прямой рукой, и вода уходит вниз вместо того, чтобы уйти назад. Разбираем первую фазу: как поставить кисть и предплечье в опору и только потом включать усилие.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м скайлинг спокойно"],[100,"4х25м i20: упражнение «плавание с паузой в момент входа руки»"]],main:[[200,"8х25м ноги дельфином на спине в ластах, i20","Движение от таза, стопы у поверхности не выпрыгивают. Это ещё и разгрузка плеча перед работой руками."],[100,"4х25м i20: упражнение «только первая фаза гребка, двумя руками одновременно»"],[200,"8х25м кроль с мал лоп, i25: кисть всегда ниже локтя","Лопатка подчёркивает провал локтя. Если рука проваливается — сделайте паузу после входа и заново поставьте предплечье."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, акцент на захват","В брассе захват — это разведение до линии плеч, а не за неё. На спине — постановка кисти сразу после входа мизинцем."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Если число гребков упало по сравнению с прошлым разом, значит захват стал держать воду лучше."]],cool:[[100,"100м в трубке спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:7,vol:1500,note:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где начинающие теряют бо…",story:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где начинающие теряют больше всего. Рука выходит из воды раньше времени, у бедра усилие исчезает, и половина гребка пропадает впустую. Сегодня доводим руку до конца на каждом отрезке.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м упражнение «плавание с касанием бедра большим пальцем»"],[100,"4х25м i20: упражнение «только окончание гребка»"]],main:[[200,"8х25м ноги кролем с доской, i20, считаем удары","Держите одинаковое число ударов на всех отрезках. Как только начали частить — усилие ушло из бедра в колено."],[100,"4х25м i20: упражнение «только окончание гребка», акцент на ускорение кисти"],[200,"8х25м кроль с мал лоп, i25: доводим руку до бедра","Кисть должна ускоряться к концу гребка, а не замедляться. Ощущение — как будто вы отталкиваетесь от воды назад."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, акцент на окончание гребка","В брассе окончание — это быстрое сведение локтей перед выведением рук вперёд. На спине — касание бедра большим пальцем."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Полное окончание гребка обычно снимает один-два гребка с отрезка — проверьте на себе."]],cool:[[100,"100м спина спокойно"],[100,"100м кроль свободно на минимальное число гребков"]]},
      {n:8,vol:1500,note:"Шаг гребка — сколько метров вы проезжаете за одно движение руки",story:"Шаг гребка — сколько метров вы проезжаете за одно движение руки. Это главный показатель мощности: два пловца с одинаковым временем могут отличаться на пять гребков, и у того, кто сделал меньше, запас больше. Вся тренировка построена вокруг одной цифры.",warm:[[200,"200м спокойно: 100м кроль с подсчётом гребков + 100м спина"],[100,"100м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[200,"8х25м ноги в ластах на низкой амплитуде, i20","Стопы почти не выходят из воды, работа только от бедра. Так ноги держат тело, а не толкают его рывками."],[100,"4х25м i20: упражнение «плавание на прямых руках»"],[200,"8х25м кроль со средними лопатками и колобашкой, i30, считаем гребки","С лопатками число гребков падает само. Запомните его — в последней серии нужно будет подойти к нему без инвентаря."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, на минимальное число гребков","На брассе шаг гребка определяется скольжением: не начинайте следующий цикл, пока тело ещё едет."],[100,"4х25м кроль без инвентаря: то же число гребков, что было с лопатками, i30","Замер тренировки. Разрыв между «с лопатками» и «без» — это ваш точный резерв мощности в гребках."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:9,vol:1500,note:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу",story:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу. Поэтому работаем контрастом: сначала лопатки утяжеляют каждый гребок, а сразу после мы их снимаем — и несколько минут вода кажется пустой. Именно в этот момент и запоминается ощущение свободного мощного гребка.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м в трубке спокойно"],[100,"4х25м i20: скайлинг"]],main:[[200,"8х25м ноги в ластах, i20","Амплитуда небольшая, движение от бедра. Ноги готовят тело к тому, что дальше руки будут перегружены."],[100,"4х25м i20: упражнение «плавание на кулаках»"],[200,"8х25м кроль со средними лопатками, i30, мощно и плавно","С лопатками тянет частить. Допустим рост до трёх гребков, больше — значит вы уже суетитесь."],[100,"100м откуп спокойно на спине"],[200,"8х25м без лопаток, i25: четыре отрезка кролем и четыре основным стилем, удержать ту же длину гребка","Вот ради этой серии всё и делалось. Ощущение лёгкости обманчиво — не разменивайте его на частоту."],[100,"4х25м основной стиль на минимальное число гребков, i30","Замер тренировки — сегодня на своём стиле. Записывайте это число отдельно от кролевого."]],cool:[[100,"100м кроль на минимальное число гребков"],[100,"100м спина спокойно"]],safe:"Средние лопатки на этом уровне — не больше 200 м за тренировку и только при отсутствии боли в плече. Если гребок идёт с провалом локтя, лопатки закрепляют эту ошибку: сначала техника, потом инвентарь."},
      {n:10,vol:1500,note:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с…",story:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с усилием. Поэтому правило простое: плывём медленнее, чем позволяют лопатки, и следим за локтем. Мощность здесь набирается не скоростью, а качеством опоры.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м скайлинг спокойно"],[100,"4х25м i20: упражнение «плавание с паузой в момент входа руки»"]],main:[[200,"8х25м ноги кролем на боку, i25","По четыре отрезка на каждый бок. Плечо вытянутой руки у уха, тело вытянуто — это положение потом нужно удержать под лопатками."],[100,"4х25м i20: упражнение «только первая фаза гребка двумя руками»"],[200,"8х25м кроль со средними лопатками, i30, мощно и плавно, без ускорения","Скорость руки ниже привычной. Если плечо начинает ныть или кисть уходит выше локтя — снимайте лопатки и доплывайте маленькими."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль без инвентаря, i30","Своим стилем плывём без лопаток: собственная рука после большой площади опоры кажется маленькой, и это надо перебороть длиной гребка."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Ощущение опоры после лопаток держится минут десять — используйте его."]],cool:[[100,"100м в трубке ноги кролем спокойно"],[100,"100м спина спокойно"]],safe:"Средние лопатки на этом уровне — не больше 200 м за тренировку. При боли или дискомфорте в плече серия плывётся маленькими лопатками или без них: техника всегда важнее инвентаря."},
      {n:11,vol:1500,note:"Прежде чем толкать воду, её нужно почувствовать",story:"Прежде чем толкать воду, её нужно почувствовать. Скайлинг — движение ладонью почти без продвижения — учит именно этому: находить плотную воду и удерживать её. Тренировка кажется лёгкой, но именно она чаще всего снимает лишний гребок с отрезка.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м: 50м скайлинг + 50м спокойно"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[200,"8х25м ноги в ластах, руки в стрелке, i20","Руки вытянуты, голова между ними. Задача — почувствовать, как тело едет ровно, без раскачивания."],[100,"4х25м i20: скайлинг, ладонь ищет опору"],[200,"8х25м кроль, i25: 12,5м скайлинг + доплывание мощно и плавно","Сразу после скайлинга ладонь чувствительнее всего. Первые гребки после него должны быть самыми длинными."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, считаем гребки","На брассе чувство воды проверяется в разведении рук, на спине — в постановке кисти сразу после входа."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Скайлинг обычно даёт эффект в тот же день — сравните с прошлым результатом."]],cool:[[100,"100м спина спокойно"],[100,"100м скольжений с бортика"]]},
      {n:12,vol:1500,note:"Держать мощный гребок двадцать пять метров умеет почти каждый",story:"Держать мощный гребок двадцать пять метров умеет почти каждый. Держать его сто — уже сложнее. Здесь отрезки длиннее, а требование то же: ровное число гребков от начала до конца. Это честная проверка того, настоящая у вас мощность или разовая.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м в трубке спокойно, считаем гребки"],[100,"4х25м i20: упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"]],main:[[200,"8х25м ноги с доской, i20","Ровная работа без рывков. Ноги нужны для того, чтобы на длинных отрезках таз не проваливался."],[100,"4х25м i20: плавание на минимальное число гребков"],[200,"2х100м кроль с колобашкой и мал лоп, i45: разброс гребков не больше трёх","Записывайте гребки по каждому полтиннику отдельно. Обычно разваливается вторая — именно там и начинается работа."],[100,"100м откуп спокойно на спине"],[200,"200м основной стиль без инвентаря: удерживаем число гребков всю дистанцию","Скорость свободная, приоритет один — длина. Если гребков стало больше чем на три, сбросьте темп, но не длину."],[100,"4х25м кроль на минимальное число гребков, i30","Замер тренировки. После длинной работы гребок обычно длиннее обычного — поймайте это состояние."]],cool:[[100,"100м произвольно"],[100,"100м спина: работа двумя руками одновременно"]]},
      {n:13,vol:1500,note:"Мощность в кроле и мощность в других стилях — разные вещи",story:"Мощность в кроле и мощность в других стилях — разные вещи. В брассе тяга идёт от разведения и сведения рук, на спине — от постановки кисти сразу после входа. Проходим стили по очереди и в каждом ищем свою точку приложения силы.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской: 50м кроль + 50м брасс"],[100,"4х25м i20: по одному отрезку спиной и брассом, два отрезка кролем"]],main:[[200,"8х25м ноги в ластах, i20","Движение от бедра и таза. Ноги здесь готовят корпус к работе в разных стилях."],[100,"4х25м i20: упражнение «руки брасс / ноги кроль»"],[200,"8х25м по стилям с мал лоп, i30: 3 спина, 3 брасс, 2 кроль","Короткие серии на каждый стиль — так лопатки не успевают перегрузить плечо."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, считаем гребки","Записывайте число гребков. Свой стиль после серии по стилям ощущается иначе — сравните с началом тренировки."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Кроль после других стилей всегда кажется лёгким — используйте это."]],cool:[[100,"100м спина спокойно"],[100,"100м в трубке ноги брассом"]]},
      {n:14,vol:1500,note:"На спине мощность строится иначе: тело держится только положением таза, а гребок идёт под вод…",story:"На спине мощность строится иначе: тело держится только положением таза, а гребок идёт под водой почти прямой траекторией. Начинающие на спине почти всегда гребут поверхностно и коротко. Разбираем это отдельно — заодно спина хорошо разгружает плечо после кролевых объёмов.",warm:[[200,"200м спокойно: 100м спина + 100м кроль"],[100,"100м на спине: 50м «одна рука работает, вторая у бедра» + 50м «6-1-6»"],[100,"4х25м i20: упражнение «часы» — остановка руки в вертикальном положении"]],main:[[200,"8х25м ноги на спине в стрелочке, i25","Таз у поверхности, колени под водой. Если из воды показались колени, значит работа идёт вниз, а не назад."],[100,"4х25м i20: скайлинг на спине"],[200,"8х25м спина с мал лоп, i30, считаем гребки","Кисть входит мизинцем, локоть уходит под воду и сгибается — прямой рукой на спине протянуть воду невозможно."],[100,"100м откуп спокойно"],[200,"8х25м основной стиль, i30","Возвращаемся к своему стилю: после спины плечи разгружены и гребок обычно получается длиннее."],[100,"4х25м спина без инвентаря на минимальное число гребков, i30","Замер тренировки — сегодня на спине. Записывайте его отдельно от кролевого, это разные цифры."]],cool:[[100,"100м кроль спокойно на минимальное число гребков"],[100,"100м произвольно"]]},
      {n:15,vol:1500,note:"Сборная тренировка: захват, окончание гребка, ноги, работа с инвентарём и без него — всё в од…",story:"Сборная тренировка: захват, окончание гребка, ноги, работа с инвентарём и без него — всё в одном занятии. Заканчивается контрольным замером: четыре отрезка по 25 м с фиксацией времени и числа гребков. Запишите обе цифры и вернитесь к ним через месяц.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м упражнения: 50м скайлинг + 50м на кулаках"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[200,"8х25м ноги, i25: четыре отрезка в ластах, четыре без","Сравните ощущение. Без ласт задача не догнать скорость, а сохранить то же положение таза."],[100,"4х25м i20: два отрезка «только первая фаза», два отрезка «только окончание гребка»"],[200,"8х25м кроль с мал лоп и колобашкой, i25","Мощно и плавно, без ускорения. Это подготовка к замеру, а не соревнование с самим собой."],[100,"100м откуп спокойно на спине"],[200,"8х25м основной стиль, i30, считаем гребки","Свой стиль перед замером. Если число гребков выросло больше чем на три по сравнению с началом тренировки, значит нагрузка была великовата."],[100,"4х25м кроль без инвентаря i60: контрольный замер — время и число гребков","Плывите мощно и плавно, а не изо всех сил. Показатель — это время при минимальном числе гребков."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]}
    ]},
    mo_s:{level:"Средний",vol:"2200 м",w:[
      {n:1,vol:2200,note:"Мощность — это не скорость",story:"Мощность — это не скорость. Как только пловец уходит на максимум, он почти всегда начинает рвать воду: рука проскальзывает, гребков становится больше, а продвижение падает. Поэтому работаем мощно и плавно, а судьёй становится не секундомер, а количество гребков. Тема тренировки — подводная фаза: захват, подтягивание, отталкивание.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м в трубке: 100м на кулаках + 100м с акцентом на высокий локоть"],[100,"4х25м i20: упражнение «только первая фаза гребка, двумя руками одновременно»"]],main:[[300,"6х50м ноги дельфином в ластах, режим 1:15: 25м мощно и плавно + 25м свободно","Движение идёт от груди и таза, колени почти не сгибаются. Мощно — не значит с размаху: широкая амплитуда быстро убивает стопу и ничего не добавляет."],[100,"4х25м i20: упражнение «скайлинг» — ищем опору ладонью, почти без продвижения"],[300,"6х50м руки с колобашкой и средними лопатками, режим 1:25, мощно и плавно","Кисть всегда ниже локтя. Лопатка увеличивает площадь, и соблазн протащить воду прямой рукой здесь максимальный — именно это и надо не допустить."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, с подсчётом гребков","На своём стиле длина гребка теряется первой. Держите число гребков в пределах трёх от первого отрезка, даже если придётся плыть медленнее."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки: запишите лучшее число гребков на 25 м. Инвентаря нет — остаётся только ваш собственный гребок, ради него всё и делалось."]],cool:[[150,"150м спина: работа двумя руками одновременно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:2,vol:2200,note:"Колобашка убирает ноги, и обмануть себя становится нечем: вперёд вас двигают только руки",story:"Колобашка убирает ноги, и обмануть себя становится нечем: вперёд вас двигают только руки. Это самый честный способ увидеть, сколько на самом деле даёт ваш гребок. Плывём длинно и мощно, следим за числом гребков — как только оно поползло вверх, работа превратилась в барахтанье.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м руки с колобашкой спокойно, считаем гребки на каждом полтиннике"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[300,"6х50м ноги кролем без доски, руки вдоль тела, режим 1:30 — считаем удары","Без доски сразу видно положение таза. Живот подобран, колени не выходят на поверхность, движение от бедра."],[100,"4х25м i20: упражнение «гребок только одной рукой», по два отрезка на руку"],[300,"6х50м руки с колобашкой, режим 1:25, мощно и плавно: удерживаем число гребков","Ладонь работает как опора, а тянет спина и широчайшие. Если плечо забивается — значит вы тянете рукой, а не корпусом."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль с колобашкой, режим 1:30","Свой стиль без ног — самая неудобная работа этой тренировки. Если техника рассыпается, снимите колобашку и доплывите серию в координации."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Сравните ощущение с работой на колобашке: тело должно держаться так же высоко, только теперь за счёт ног."]],cool:[[150,"150м в трубке ноги брассом спокойно"],[100,"100м спина спокойно"]]},
      {n:3,vol:2200,note:"Ноги дают опору всему телу: если таз провалился, даже самый сильный гребок будет тащить вас в…",story:"Ноги дают опору всему телу: если таз провалился, даже самый сильный гребок будет тащить вас вверх, а не вперёд. Здесь ноги — главный герой тренировки, и работаем мы ими так же, как руками: мощно, плавно и с подсчётом. Ласты и работа без них чередуются, чтобы стопа училась и толкать, и держать форму.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской спокойно: 100м кроль + 100м брасс"],[100,"4х25м i20: упражнение «ноги кролем на боку», по два отрезка на каждый бок"]],main:[[300,"6х50м ноги в ластах, режим 1:15, мощно и плавно","Стопа расслаблена, работа от бедра. Ласта должна прогибаться под давлением — если она просто шлёпает, вы бьёте коленом."],[100,"4х25м i20: упражнение «ноги дельфин на спине» — движение от таза"],[300,"6х50м ноги без ласт с доской, режим 1:30, считаем удары","Без ласт число ударов растёт само собой. Задача обратная: удержать то же число, что на первом отрезке, и не частить."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, ноги активные","Здесь ноги проверяются на своём стиле. В брассе следите, чтобы толчок шёл в стороны и назад, а не вниз."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. После ласт тело помнит высокое положение — постарайтесь удержать его своими ногами."]],cool:[[150,"150м кроль с колобашкой спокойно, ноги отдыхают"],[100,"100м спина спокойно"]]},
      {n:4,vol:2200,note:"Толчок от стенки — единственный момент, когда пловец разгоняется быстрее, чем способен плыть…",story:"Толчок от стенки — единственный момент, когда пловец разгоняется быстрее, чем способен плыть, и почти единственный, который любители не тренируют вообще. Разбираем мощность толчка и первые метры после него: чем дольше держится скорость после стенки, тем меньше гребков уходит на весь отрезок.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м в трубке спокойно, тело вытянуто в одну линию"],[100,"4х25м i20: толчок от стенки и скольжение в стрелке до полной остановки, дальше спокойно"]],main:[[300,"6х50м i30: мощный толчок и 5 движений ногами под водой, дальше спокойно до бортика","Стопы ставятся на стенку на глубине 30–40 см, тело уже в стрелке до толчка. Голова между руками, одна кисть на другой — любой излом сводит толчок на нет."],[100,"4х25м i20: упражнение «скольжение на спине в стрелочке»"],[300,"6х50м кроль, режим 1:25, акцент на первые пять метров после стенки, считаем гребки","Первый гребок начинается после всплытия. Хороший толчок экономит один-два гребка на каждом отрезке — это и есть его цена."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, с акцентом на выход из поворота","На брассе и дельфине выход из-под воды — самая мощная часть отрезка. Не всплывайте раньше, чем скорость толчка начнёт падать."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Отрезок начинается с толчка — считайте, сколько гребков нужно, чтобы дойти до стенки."]],cool:[[100,"100м скольжений с бортика: толчок, скольжение до остановки, дальше спокойно"],[150,"150м спина спокойно"]]},
      {n:5,vol:2200,note:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает",story:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает. Здесь мы разводим руки и смотрим на каждую отдельно: где опора хуже, где гребок короче, где тело заваливается. Разница между руками — это чистый резерв мощности, который не требует ни силы, ни объёма.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м упражнение «2 гребка правой, 2 гребка левой»"],[100,"4х25м i20: «один гребок правой, один левой, один двумя руками»"]],main:[[300,"6х50м ноги на боку с вытянутой рукой, режим 1:35 — по 25м на каждый бок","На боку сразу видно, какая сторона держит тело хуже. Плечо вытянутой руки прижато к уху, взгляд вниз."],[100,"4х25м i20: упражнение «гребок только одной рукой», вторая у бедра"],[300,"6х50м кроль одной рукой с колобашкой и средней лопаткой, режим 1:35: по отрезку на руку","Считайте гребки отдельно для правой и левой. Разница больше двух гребков — слабую руку в следующих тренировках грузим дополнительно."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30","На симметричных стилях перекос виден по траектории: тело уводит в сторону. Виновата не голова, а более короткий гребок одной рукой."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Обратите внимание, с какой стороны вы дышите — чаще всего именно эта рука короче."]],cool:[[150,"150м спина: работа двумя руками одновременно"],[100,"100м произвольно"]]},
      {n:6,vol:2200,note:"Захват — самая недооценённая часть гребка",story:"Захват — самая недооценённая часть гребка. Большинство любителей начинает тянуть слишком рано, прямой рукой, и вода уходит вниз вместо того, чтобы уйти назад. Разбираем первую фазу: как поставить кисть и предплечье в опору и только потом включать усилие.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м скайлинг спокойно"],[100,"4х25м i20: упражнение «плавание с паузой в момент входа руки»"]],main:[[300,"6х50м ноги дельфином на спине в ластах, режим 1:15","Движение от таза, стопы у поверхности не выпрыгивают. Это ещё и разгрузка плеча перед основной работой."],[100,"4х25м i20: упражнение «только первая фаза гребка, двумя руками одновременно»"],[300,"6х50м кроль с чашечками, режим 1:25: кисть всегда ниже локтя","Сопротивление подчёркивает провал локтя лучше любого видео. Если рука проваливается — сделайте паузу после входа и заново поставьте предплечье."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, акцент на захват","В брассе захват — это разведение до линии плеч, а не за неё. В дельфине — постановка обеих кистей до начала подтягивания."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Если число гребков упало по сравнению с прошлым разом, значит захват стал держать воду лучше."]],cool:[[150,"150м в трубке спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:7,vol:2200,note:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют боль…",story:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют больше всего. Рука выходит из воды раньше времени, у бедра усилие исчезает, и половина гребка пропадает впустую. Сегодня доводим руку до конца на каждом отрезке.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м упражнение «плавание с касанием бедра большим пальцем»"],[100,"4х25м i20: упражнение «только окончание гребка»"]],main:[[300,"6х50м ноги кролем с доской, режим 1:30, считаем удары","Держите одинаковое число ударов на всех отрезках. Как только начали частить — усилие ушло из бедра в колено."],[100,"4х25м i20: упражнение «только окончание гребка», акцент на ускорение кисти"],[300,"6х50м кроль со средними лопатками, режим 1:25: доводим руку до бедра","Кисть должна ускоряться к концу гребка, а не замедляться. Ощущение — как будто вы отталкиваетесь от воды назад, а не тянете её."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, акцент на окончание гребка","В дельфине окончание — это выброс кистей мимо бёдер. В брассе — быстрое сведение локтей перед выведением рук вперёд."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Полное окончание гребка обычно снимает один-два гребка с отрезка — проверьте на себе."]],cool:[[100,"100м спина спокойно"],[150,"150м кроль свободно на минимальное число гребков"]]},
      {n:8,vol:2200,note:"Шаг гребка — сколько метров вы проезжаете за одно движение руки",story:"Шаг гребка — сколько метров вы проезжаете за одно движение руки. Это и есть главный показатель мощности: два пловца с одинаковым временем на полтиннике могут отличаться на пять гребков, и у того, кто сделал меньше, запас на дистанции больше. Вся тренировка построена вокруг одной цифры.",warm:[[200,"200м спокойно: 100м кроль с подсчётом гребков + 100м спина"],[200,"200м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[300,"6х50м ноги в ластах на низкой амплитуде, режим 1:15","Низкая амплитуда — работа только от бедра, стопы почти не выходят из воды. Так ноги держат тело, а не толкают его рывками."],[100,"4х25м i20: упражнение «плавание на прямых руках»"],[300,"6х50м кроль со средними лопатками и колобашкой, режим 1:25, считаем гребки","С лопатками число гребков падает само. Запомните это число — на последней серии нужно будет подойти к нему без инвентаря."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, на минимальное число гребков","На брассе шаг гребка определяется скольжением: не начинайте следующий цикл, пока тело ещё едет."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря: то же число гребков, что было с лопатками, i30","Замер тренировки. Разрыв между «с лопатками» и «без» — это ваш точный резерв мощности в гребках."]],cool:[[150,"150м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:9,vol:2200,note:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу",story:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу. Поэтому работаем контрастом: сначала чашечки утяжеляют каждый гребок, а сразу после мы их снимаем — и несколько минут вода кажется пустой. Именно в этот момент и запоминается ощущение мощного, свободного гребка.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м в трубке: 100м на кулаках + 100м координация"],[100,"4х25м i20: скайлинг"]],main:[[300,"6х50м ноги дельфином в ластах, режим 1:15","Амплитуда небольшая, движение от груди. Ноги готовят тело к тому, что дальше руки будут перегружены."],[100,"4х25м i20: упражнение «плавание на кулаках»"],[300,"6х50м кроль с чашечками, режим 1:25, мощно и плавно","С сопротивлением тянет частить. Допустим рост до трёх гребков на полтиннике, больше — значит вы уже суетитесь."],[150,"150м откуп спокойно на спине"],[300,"6х50м кроль без чашечек, режим 1:20: удержать ту же длину гребка","Вот ради этой серии всё и делалось. Ощущение лёгкости обманчиво — не разменивайте его на частоту, держите длину."],[100,"100м откуп спокойно"],[200,"8х25м основной стиль на минимальное число гребков, i30","Замер тренировки — сегодня на своём стиле. Записывайте это число отдельно от кролевого."]],cool:[[100,"100м кроль на минимальное число гребков"],[150,"150м спина спокойно"]]},
      {n:10,vol:2200,note:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с…",story:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с усилием. Поэтому правило простое: плывём медленнее, чем позволяют лопатки, и следим за локтем. Мощность здесь набирается не скоростью, а качеством опоры.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м скайлинг спокойно"],[100,"4х25м i20: упражнение «плавание с паузой в момент входа руки»"]],main:[[300,"6х50м ноги кролем без доски на боку, режим 1:35","По 25 м на каждый бок. Плечо вытянутой руки у уха, тело вытянуто — это положение потом нужно удержать под лопатками."],[100,"4х25м i20: упражнение «только первая фаза гребка двумя руками»"],[300,"6х50м кроль со средними лопатками, режим 1:25, мощно и плавно, без ускорения","Скорость руки должна быть ниже привычной. Если плечо начинает ныть или кисть уходит выше локтя — снимайте лопатки."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль без инвентаря, режим 1:30","Своим стилем плывём без лопаток: после большой площади опоры собственная рука кажется маленькой, и это ощущение надо перебороть длиной гребка."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Ощущение опоры после лопаток держится минут десять — используйте его."]],cool:[[150,"150м в трубке ноги кролем спокойно"],[100,"100м спина спокойно"]],safe:"Средние лопатки в этой тренировке — 300 м. При боли или прострелах в плече серия плывётся маленькими лопатками или без них: техника всегда важнее инвентаря."},
      {n:11,vol:2200,note:"Прежде чем толкать воду, её нужно почувствовать",story:"Прежде чем толкать воду, её нужно почувствовать. Скайлинг — движение ладонью почти без продвижения — учит именно этому: находить плотную воду и удерживать её. Тренировка получается обманчиво лёгкой, но именно она чаще всего снимает пару гребков с полтинника.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м: 100м скайлинг + 100м спокойно"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[300,"6х50м ноги в ластах, руки в стрелке, режим 1:15","Руки вытянуты, голова между ними. Задача — почувствовать, как тело едет ровно, без раскачивания."],[100,"4х25м i20: скайлинг, ладонь ищет опору"],[300,"6х50м кроль, режим 1:30: 12,5м скайлинг + доплывание мощно и плавно","Сразу после скайлинга ладонь чувствительнее всего. Первые гребки после него должны быть самыми длинными на отрезке."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, считаем гребки","На брассе чувство воды проверяется в разведении рук, на спине — в постановке кисти сразу после входа."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Скайлинг обычно даёт эффект в тот же день — сравните с прошлым результатом."]],cool:[[150,"150м спина спокойно"],[100,"100м скольжений с бортика"]]},
      {n:12,vol:2200,note:"Держать мощный гребок двадцать пять метров умеет почти каждый",story:"Держать мощный гребок двадцать пять метров умеет почти каждый. Держать его двести — почти никто. Здесь отрезки длиннее, а требование то же: ровное число гребков от первого полтинника до последней. Это честная проверка того, настоящая у вас мощность или разовая.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м в трубке спокойно, считаем гребки на каждом полтиннике"],[100,"4х25м i20: упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"]],main:[[300,"6х50м ноги с доской, режим 1:30","Ровная работа без рывков. Ноги нужны для того, чтобы на длинных отрезках таз не проваливался."],[100,"4х25м i20: плавание на минимальное число гребков"],[300,"3х100м кроль с колобашкой и средними лопатками, режим 2:10: разброс гребков не больше трёх","Записывайте гребки по каждому полтиннику отдельно. Обычно разваливается вторая — именно там и начинается настоящая работа."],[150,"150м откуп спокойно на спине"],[300,"300м основной стиль без инвентаря: удерживаем число гребков всю дистанцию","Скорость свободная, приоритет один — длина. Если число гребков выросло больше чем на три, сбросьте темп, но не длину."],[100,"100м откуп спокойно"],[200,"8х25м кроль на минимальное число гребков, i30","Замер тренировки. После длинной работы гребок обычно длиннее обычного — поймайте это состояние."]],cool:[[100,"100м произвольно"],[150,"150м спина: работа двумя руками одновременно"]]},
      {n:13,vol:2200,note:"Мощность в кроле и мощность в комплексе — разные вещи",story:"Мощность в кроле и мощность в комплексе — разные вещи. В дельфине тяга идёт от корпуса, в брассе — от разведения и сведения рук, на спине — от постановки кисти сразу после входа. Проходим все четыре стиля и в каждом ищем свою точку приложения силы.",warm:[[200,"200м комплекс по 50м, спокойно"],[200,"200м ноги комплекс без доски"],[100,"4х25м i20: по одному отрезку каждым стилем"]],main:[[300,"6х50м ноги дельфином в ластах, режим 1:15","Волна идёт от груди через таз к стопам. Это базовое движение для дельфина и заодно подготовка спины к работе."],[100,"4х25м i20: упражнение «руки дельфин / ноги кроль»"],[300,"6х50м по стилям со средними лопатками, режим 1:40: 2 спина, 2 брасс, 2 кроль","Короткие серии на каждый стиль — так лопатки не успевают перегрузить плечо. Дельфин с лопатками здесь не берём."],[150,"150м откуп спокойно на спине"],[300,"3х100м комплекс, режим 2:20, считаем гребки на каждой 25","Записывайте четыре числа. Стиль с самым большим числом гребков — ваша слабая точка в комплексе, ей и будете заниматься отдельно."],[100,"100м откуп спокойно"],[200,"8х25м основной стиль на минимальное число гребков, i30","Замер тренировки — сегодня на своём стиле. После комплекса он ощущается легче обычного, используйте это и постарайтесь снять лишний гребок."]],cool:[[150,"150м спина спокойно"],[100,"100м в трубке ноги брассом"]]},
      {n:14,vol:2200,note:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза…",story:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза, а гребок идёт под водой почти прямой траекторией. Любители на спине почти всегда гребут поверхностно и коротко. Разбираем это отдельно — заодно спина хорошо разгружает плечо после кролевых объёмов.",warm:[[200,"200м спокойно: 100м спина + 100м кроль"],[200,"200м на спине: 100м «одна рука работает, вторая у бедра» + 100м «6-1-6»"],[100,"4х25м i20: упражнение «часы» — остановка руки в вертикальном положении"]],main:[[300,"6х50м ноги на спине в стрелочке, режим 1:30","Таз у поверхности, колени под водой. Если из воды показались колени, значит работа идёт вниз, а не назад."],[100,"4х25м i20: скайлинг на спине"],[300,"6х50м спина со средними лопатками, режим 1:30, считаем гребки","Кисть входит мизинцем, локоть уходит под воду и сгибается — прямой рукой на спине протянуть воду невозможно, лопатка это только подчеркнёт."],[150,"150м откуп спокойно"],[300,"6х50м основной стиль, режим 1:30","Возвращаемся к своему стилю: после спины плечи разгружены и гребок обычно получается длиннее."],[100,"100м откуп спокойно"],[200,"8х25м спина без инвентаря на минимальное число гребков, i30","Замер тренировки — сегодня на спине. Записывайте его отдельно от кролевого, это разные цифры."]],cool:[[150,"150м кроль спокойно на минимальное число гребков"],[100,"100м произвольно"]]},
      {n:15,vol:2200,note:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё…",story:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё в одном занятии. Заканчивается контрольным замером: четыре полтинника с фиксацией времени и числа гребков. Запишите обе цифры и вернитесь к ним через месяц — именно эта пара чисел показывает, растёт ли мощность.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м упражнения: 100м скайлинг + 100м на кулаках"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[300,"6х50м ноги, режим 1:25: три отрезка в ластах, три без","Сравните ощущение. Без ласт задача не догнать скорость, а сохранить то же положение таза."],[100,"4х25м i20: два отрезка «только первая фаза», два отрезка «только окончание гребка»"],[300,"6х50м кроль со средними лопатками и колобашкой, режим 1:25","Мощно и плавно, без ускорения. Это подготовка к замеру, а не соревнование с самим собой."],[150,"150м откуп спокойно на спине"],[300,"6х50м основной стиль, режим 1:30, считаем гребки","Свой стиль перед замером. Если число гребков выросло больше чем на три по сравнению с началом тренировки, значит нагрузка была великовата — сбавьте усилие."],[100,"100м откуп спокойно"],[200,"4х50м кроль без инвентаря i60: контрольный замер — время и число гребков","Плывите мощно и плавно, а не на максимум. Показатель — это время при минимальном числе гребков, а не время любой ценой."]],cool:[[150,"150м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]}
    ]},
    mo_p:{level:"Продвинутый",vol:"3000 м",w:[
      {n:1,vol:3000,note:"Мощность — это не скорость",story:"Мощность — это не скорость. Как только пловец уходит на максимум, он почти всегда начинает рвать воду: рука проскальзывает, гребков становится больше, а продвижение падает. Поэтому здесь мы работаем мощно и плавно, а главным судьёй становится не секундомер, а количество гребков. Тема первой тренировки — подводная фаза: захват, подтягивание, отталкивание.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м в трубке: 100м на кулаках + 100м с акцентом на высокий локоть"],[100,"4х25м i20: упражнение «только первая фаза гребка, двумя руками одновременно»"]],main:[[300,"6х50м ноги дельфином в ластах, режим 1:10: 25м мощно и плавно + 25м свободно","Движение идёт от груди и таза, колени почти не сгибаются. Мощно — не значит с размаху: широкая амплитуда на ластах быстро убивает стопу и ничего не добавляет."],[100,"4х25м i20: упражнение «скайлинг» — ищем опору ладонью, почти без продвижения"],[400,"8х50м кроль с чашечками, режим 1:20, считаем гребки на каждом отрезке","Запишите число гребков на первом полтиннике. Если к концу серии оно выросло больше чем на три — вы перешли на рывок, сбавьте усилие и восстановите длину."],[200,"200м откуп спокойно на спине"],[400,"8х50м руки с колобашкой и средними лопатками, режим 1:15, мощно и плавно, без ускорения","Кисть всегда ниже локтя. Лопатка увеличивает площадь, поэтому соблазн протащить воду прямой рукой здесь максимальный — именно это и надо не допустить."],[300,"6х50м основной стиль, режим 1:20, с подсчётом гребков","На своём стиле длина гребка теряется первой. Держите число гребков в пределах трёх от первого отрезка, даже если для этого придётся плыть медленнее."],[200,"200м откуп: 100м спина + 100м кроль"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки: запишите лучшее число гребков на 25 м. Инвентаря нет — значит остаётся только ваш собственный гребок, ради него всё и делалось."]],cool:[[200,"200м спина: работа двумя руками одновременно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:2,vol:3000,note:"Колобашка убирает ноги, и обмануть себя становится нечем: вперёд вас двигают только руки",story:"Колобашка убирает ноги, и обмануть себя становится нечем: вперёд вас двигают только руки. Это самый честный способ увидеть, сколько на самом деле даёт ваш гребок. Плывём длинно и мощно, следим за числом гребков — как только оно поползло вверх, работа превратилась в барахтанье.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"200м руки с колобашкой спокойно, считаем гребки на каждом полтиннике"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[300,"6х50м ноги кролем без доски, руки вдоль тела, режим 1:20 — считаем удары","Без доски сразу видно положение таза. Живот подобран, колени не выходят на поверхность, движение от бедра."],[100,"4х25м i20: упражнение «гребок только одной рукой», по два отрезка на руку"],[400,"8х50м руки с колобашкой, режим 1:15, мощно и плавно: удерживаем число гребков","Кулаки сжимать не нужно, но и вцепляться в воду тоже: ладонь работает как опора, а тянет спина и широчайшие."],[200,"200м откуп спокойно на спине"],[400,"4х100м руки с колобашкой и средними лопатками, режим 2:00","На сотне гребок разваливается во второй половине. Считайте гребки на каждом полтиннике: разница между первой и второй — это и есть ваш запас."],[100,"100м откуп спокойно"],[400,"8х50м основной стиль с колобашкой, режим 1:20","Свой стиль без ног — самая неудобная работа этой тренировки. Если техника рассыпается, снимите колобашку и доплывите серию в координации."],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Сравните ощущение с работой на колобашке: тело должно держаться так же высоко, только теперь за счёт ног."]],cool:[[100,"100м в трубке ноги брассом спокойно"],[200,"200м спина спокойно"]]},
      {n:3,vol:3000,note:"Ноги дают опору всему телу: если таз провалился, любой, даже самый сильный гребок будет тащит…",story:"Ноги дают опору всему телу: если таз провалился, любой, даже самый сильный гребок будет тащить вас вверх, а не вперёд. Здесь ноги — главный герой тренировки, и работаем мы ими так же, как руками: мощно, плавно и с подсчётом. Ласты и работа без них чередуются, чтобы стопа училась и толкать, и держать форму.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м координация"],[200,"200м ноги с доской спокойно: 100м кроль + 100м брасс"],[100,"4х25м i20: упражнение «ноги кролем на боку», по два отрезка на каждый бок"]],main:[[400,"8х50м ноги в ластах, режим 1:05, мощно и плавно","Стопа расслаблена, работа идёт от бедра. Ласта должна прогибаться под давлением — если она просто шлёпает, вы бьёте коленом."],[100,"4х25м i20: упражнение «ноги дельфин на спине» — движение от таза"],[300,"6х50м ноги без ласт с доской, режим 1:25, считаем удары на отрезке","Без ласт число ударов растёт само собой. Задача обратная: удержать то же число, что на первом отрезке, и не частить."],[200,"200м откуп спокойно на спине"],[400,"8х50м кроль в ластах с акцентом на ноги, режим 1:10: число гребков минимальное","Ласты дают ход, поэтому руке легко проскочить воду впустую. Гребок должен оставаться таким же длинным, как без ласт."],[400,"8х50м основной стиль, режим 1:20, ноги активные","Здесь ноги проверяются на своём стиле. В брассе следите, чтобы толчок шёл в стороны и назад, а не вниз."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. После ласт тело помнит высокое положение — постарайтесь удержать его своими ногами."]],cool:[[200,"200м кроль с колобашкой спокойно, ноги отдыхают"],[100,"100м спина спокойно"]]},
      {n:4,vol:3000,note:"Толчок от стенки — единственный момент, когда пловец разгоняется быстрее, чем способен плыть…",story:"Толчок от стенки — единственный момент, когда пловец разгоняется быстрее, чем способен плыть, и почти единственный, который любители не тренируют вообще. Здесь мы разбираем мощность толчка и первые метры после него: чем дольше держится скорость после стенки, тем меньше гребков уходит на весь отрезок.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м в трубке спокойно, тело вытянуто в одну линию"],[100,"4х25м i20: толчок от стенки и скольжение в стрелке до полной остановки, дальше спокойно"]],main:[[300,"6х50м i30: мощный толчок и 5 движений ногами под водой, дальше спокойно до бортика","Стопы ставятся на стенку на глубине 30–40 см, тело уже в стрелке до толчка. Голова между руками, одна кисть на другой — любой излом сводит толчок на нет."],[100,"4х25м i20: упражнение «скольжение на спине в стрелочке»"],[400,"8х50м кроль, режим 1:15, акцент на первые пять метров после стенки, считаем гребки","Первый гребок начинается после всплытия. Считайте гребки: хороший толчок экономит один-два на каждом отрезке — это и есть его цена."],[200,"200м откуп спокойно на спине"],[400,"8х50м руки с колобашкой и средними лопатками, режим 1:15, мощно и плавно","Без ног после толчка тело проваливается быстрее. Держите таз у поверхности напряжением живота с первого метра."],[400,"8х50м основной стиль, режим 1:20, с акцентом на выход из поворота","На брассе и дельфине выход из-под воды — самая мощная часть отрезка. Не всплывайте раньше, чем скорость толчка начнёт падать."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Отрезок начинается с толчка — считайте, сколько гребков нужно, чтобы дойти до стенки."]],cool:[[100,"100м скольжений с бортика: толчок, скольжение до остановки, дальше спокойно"],[200,"200м спина спокойно"]]},
      {n:5,vol:3000,note:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает",story:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает. Здесь мы разводим руки и смотрим на каждую отдельно: где опора хуже, где гребок короче, где тело заваливается. Разница между руками — это чистый резерв мощности, который не требует ни силы, ни объёма.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"200м упражнение «2 гребка правой, 2 гребка левой»"],[100,"4х25м i20: «один гребок правой, один левой, один двумя руками»"]],main:[[300,"6х50м ноги на боку с вытянутой рукой, режим 1:25 — по 25м на каждый бок","На боку сразу видно, какая сторона держит тело хуже. Плечо вытянутой руки прижато к уху, взгляд вниз."],[100,"4х25м i20: упражнение «гребок только одной рукой», вторая у бедра"],[400,"8х50м кроль одной рукой с колобашкой и средней лопаткой, режим 1:30: по отрезку на руку","Считайте гребки отдельно для правой и левой. Разница больше двух гребков — слабую руку в следующих тренировках грузим дополнительно."],[200,"200м откуп спокойно на спине"],[400,"8х50м кроль в координации с лопатками, режим 1:15, считаем гребки","Теперь обе руки вместе. Задача — чтобы гребок слабой стороны стал таким же длинным, а не чтобы сильная тянула за двоих."],[400,"8х50м основной стиль, режим 1:20","На симметричных стилях перекос виден по траектории: тело уводит в сторону. Если уводит — виновата не голова, а более короткий гребок одной рукой."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Обратите внимание, с какой стороны вы дышите — чаще всего именно эта рука короче."]],cool:[[200,"200м спина: работа двумя руками одновременно"],[100,"100м произвольно"]]},
      {n:6,vol:3000,note:"Захват — самая недооценённая часть гребка",story:"Захват — самая недооценённая часть гребка. Большинство любителей начинает тянуть слишком рано, прямой рукой, и вода уходит вниз вместо того, чтобы уйти назад. Здесь мы разбираем первую фазу: как поставить кисть и предплечье в опору и только потом включать усилие.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м скайлинг спокойно"],[100,"4х25м i20: упражнение «плавание с паузой в момент входа руки»"]],main:[[300,"6х50м ноги дельфином на спине в ластах, режим 1:10","Движение от таза, стопы у поверхности не выпрыгивают. Это ещё и разгрузка плеча перед основной работой."],[100,"4х25м i20: упражнение «только первая фаза гребка, двумя руками одновременно»"],[400,"8х50м кроль с чашечками, режим 1:20: кисть всегда ниже локтя","Сопротивление подчёркивает провал локтя лучше любого видео. Если чувствуете, что рука проваливается — сделайте паузу после входа и заново поставьте предплечье."],[200,"200м откуп спокойно на спине"],[400,"4х100м руки с колобашкой и большими лопатками, режим 2:10, мощно и плавно","Большая лопатка прощает плохой захват и тут же его закрепляет. Плывите медленнее, чем хочется, но с правильной постановкой предплечья."],[400,"8х50м основной стиль, режим 1:20, акцент на захват","В брассе захват — это разведение до линии плеч, а не за неё. В дельфине — постановка обеих кистей до начала подтягивания."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Если число гребков упало по сравнению с прошлым разом, значит захват стал держать воду лучше."]],cool:[[200,"200м в трубке спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:7,vol:3000,note:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют боль…",story:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют больше всего. Рука выходит из воды раньше времени, у бедра усилие исчезает, и половина гребка пропадает впустую. Сегодня доводим руку до конца на каждом отрезке.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"200м упражнение «плавание с касанием бедра большим пальцем»"],[100,"4х25м i20: упражнение «только окончание гребка»"]],main:[[300,"6х50м ноги кролем с доской, режим 1:20, считаем удары","Держите одинаковое число ударов на всех отрезках. Как только начали частить — усилие ушло из бедра в колено."],[100,"4х25м i20: упражнение «только окончание гребка», акцент на ускорение кисти"],[400,"8х50м кроль со средними лопатками, режим 1:15: доводим руку до бедра","Кисть должна ускоряться к концу гребка, а не замедляться. Ощущение — как будто вы отталкиваетесь от воды назад, а не тянете её."],[200,"200м откуп спокойно на спине"],[400,"4х100м кроль с колобашкой и чашечками, режим 2:15","На сотне окончание гребка теряется первым. Считайте гребки на втором полтиннике — рост больше трёх означает, что рука начала выскакивать раньше."],[400,"8х50м основной стиль, режим 1:20, акцент на окончание гребка","В дельфине окончание — это выброс кистей мимо бёдер. В брассе — быстрое сведение локтей перед выведением рук вперёд."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Полное окончание гребка обычно снимает один-два гребка с отрезка — проверьте на себе."]],cool:[[100,"100м спина спокойно"],[200,"200м кроль свободно на минимальное число гребков"]]},
      {n:8,vol:3000,note:"Шаг гребка — сколько метров вы проезжаете за одно движение руки",story:"Шаг гребка — сколько метров вы проезжаете за одно движение руки. Это и есть главный показатель мощности: два пловца с одинаковым временем на полтиннике могут отличаться на пять гребков, и у того, кто сделал меньше, запас на дистанции больше. Вся тренировка построена вокруг одной цифры.",warm:[[300,"300м спокойно: 100м кроль с подсчётом гребков + 100м спина + 100м брасс"],[200,"200м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[300,"6х50м ноги в ластах на низкой амплитуде, режим 1:10","Низкая амплитуда — работа только от бедра, стопы почти не выходят из воды. Так ноги держат тело, а не толкают его рывками."],[100,"4х25м i20: упражнение «плавание на прямых руках»"],[400,"8х50м кроль, режим 1:15: на 2 гребка меньше обычного, время свободное","Длина берётся из двух мест: вытягивание вперёд после входа руки и доведение гребка до бедра. Не из паузы и не из задержки."],[200,"200м откуп спокойно на спине"],[400,"8х50м кроль с большими лопатками и колобашкой, режим 1:15, считаем гребки","С лопатками число гребков падает само. Запомните это число — на последней серии нужно будет подойти к нему без инвентаря."],[400,"8х50м основной стиль, режим 1:20, на минимальное число гребков","На брассе шаг гребка определяется скольжением: не начинайте следующий цикл, пока тело ещё едет."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря: то же число гребков, что было с лопатками, i30","Замер тренировки. Разрыв между «с лопатками» и «без» — это ваш точный резерв мощности в гребках."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:9,vol:3000,note:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу",story:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу. Поэтому здесь мы работаем контрастом: сначала чашечки утяжеляют каждый гребок, а сразу после мы их снимаем — и несколько минут вода кажется пустой. Именно в этот момент и запоминается ощущение мощного, свободного гребка.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"200м в трубке: 100м на кулаках + 100м координация"],[100,"4х25м i20: скайлинг"]],main:[[300,"6х50м ноги дельфином в ластах, режим 1:10","Амплитуда небольшая, движение от груди. Ноги здесь готовят тело к тому, что дальше руки будут перегружены."],[100,"4х25м i20: упражнение «плавание на кулаках»"],[400,"8х50м кроль с чашечками, режим 1:20, мощно и плавно","С сопротивлением тянет частить. Считайте гребки: с чашечками допустим рост до трёх на полтиннике, больше — значит вы частите."],[200,"200м откуп спокойно на спине"],[400,"8х50м кроль без чашечек, режим 1:15: удержать ту же длину гребка","Вот ради этой серии всё и делалось. Ощущение лёгкости обманчиво — не разменивайте его на частоту, держите длину."],[400,"8х50м основной стиль, режим 1:20: четыре отрезка с чашечками, четыре без","Тот же контраст на своём стиле. На брассе и дельфине чашечки особенно наглядно показывают, доводите ли вы гребок до конца."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. После контраста число гребков обычно лучшее за неделю — запишите его."]],cool:[[100,"100м кроль на минимальное число гребков"],[200,"200м спина спокойно"]]},
      {n:10,vol:3000,note:"Большие лопатки — самый мощный инструмент в бассейне и самый опасный",story:"Большие лопатки — самый мощный инструмент в бассейне и самый опасный. Они увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с усилием. Поэтому правило тренировки простое: плывём медленнее, чем позволяют лопатки, и следим за локтем. Мощность здесь набирается не скоростью, а качеством опоры.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м скайлинг спокойно"],[100,"4х25м i20: упражнение «плавание с паузой в момент входа руки»"]],main:[[300,"6х50м ноги кролем без доски на боку, режим 1:25","По 25 м на каждый бок. Плечо вытянутой руки у уха, тело вытянуто — это положение потом нужно будет удержать под лопатками."],[100,"4х25м i20: упражнение «только первая фаза гребка двумя руками»"],[400,"8х50м кроль с большими лопатками, режим 1:20, мощно и плавно, без ускорения","Скорость руки должна быть ниже привычной. Если плечо начинает ныть или кисть уходит выше локтя — снимайте лопатки и доплывайте серию средними."],[200,"200м откуп спокойно на спине"],[400,"4х100м кроль с большими лопатками и колобашкой, режим 2:10: число гребков ровное: разброс не больше трёх","Самая тяжёлая серия тренировки. Если второй полтинник даёт больше трёх лишних гребков, серия закончена — доплывайте откуп."],[400,"8х50м основной стиль без инвентаря, режим 1:20","Своим стилем плывём без лопаток: после большой площади опоры собственная рука кажется маленькой, и это ровно то ощущение, которое нужно перебороть длиной гребка."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Ощущение опоры после больших лопаток держится минут десять — используйте его."]],cool:[[200,"200м в трубке ноги кролем спокойно"],[100,"100м спина спокойно"]],safe:"Большие лопатки в этой тренировке — 800 м. Это верхняя граница даже для подготовленного любителя. При боли или прострелах в плече серия плывётся средними лопатками или без них: техника всегда важнее инвентаря."},
      {n:11,vol:3000,note:"Прежде чем толкать воду, её нужно почувствовать",story:"Прежде чем толкать воду, её нужно почувствовать. Скайлинг — движение ладонью почти без продвижения — учит именно этому: находить плотную воду и удерживать её. Тренировка получается обманчиво лёгкой, но именно она чаще всего снимает пару гребков с полтинника.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"200м: 100м скайлинг + 100м спокойно"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[300,"6х50м ноги в ластах, руки в стрелке, режим 1:10","Руки вытянуты, голова между ними. Задача — почувствовать, как тело едет ровно, без раскачивания."],[100,"4х25м i20: скайлинг, ладонь ищет опору"],[400,"8х50м кроль, режим 1:20: 12,5м скайлинг + доплывание мощно и плавно","Сразу после скайлинга ладонь чувствительнее всего. Первые гребки после него должны быть самыми длинными на отрезке."],[200,"200м откуп спокойно на спине"],[400,"8х50м руки с колобашкой и средними лопатками, режим 1:15","Лопатка убирает чувствительность ладони, поэтому опору теперь ищет предплечье. Локоть высоко, кисть ниже локтя."],[400,"8х50м основной стиль, режим 1:20, считаем гребки","На брассе чувство воды проверяется в разведении рук, на спине — в постановке кисти сразу после входа."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Скайлинг обычно даёт эффект в тот же день — сравните с прошлым результатом."]],cool:[[200,"200м спина спокойно"],[100,"100м скольжений с бортика"]]},
      {n:12,vol:3000,note:"Держать мощный гребок двадцать пять метров умеет почти каждый",story:"Держать мощный гребок двадцать пять метров умеет почти каждый. Держать его четыреста — почти никто. Здесь отрезки длиннее, а требование то же: одинаковое число гребков от первого полтинника до последней. Это самая честная проверка того, настоящая у вас мощность или разовая.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м в трубке спокойно, считаем гребки на каждом полтиннике"],[100,"4х25м i20: упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"]],main:[[300,"6х50м ноги с доской, режим 1:20","Ровная работа без рывков. Ноги здесь нужны для того, чтобы на длинных отрезках таз не проваливался."],[100,"4х25м i20: плавание на минимальное число гребков"],[400,"2х200м кроль с колобашкой и средними лопатками, режим 3:40: число гребков ровное: разброс не больше трёх","Записывайте гребки по каждому полтиннику отдельно. Обычно разваливается третья — именно там и начинается настоящая работа."],[200,"200м откуп спокойно на спине"],[400,"400м кроль без инвентаря: удерживаем число гребков всю дистанцию","Скорость свободная, приоритет один — длина. Если число гребков выросло больше чем на три, сбросьте темп, но не длину."],[400,"8х50м основной стиль, режим 1:20","На своём стиле держать длину на серии сложнее всего. Не гонитесь за режимом: лучше отдохнуть лишние десять секунд, чем частить."],[100,"100м откуп спокойно"],[200,"8х25м кроль на минимальное число гребков, i30","Замер тренировки. После длинной работы гребок обычно длиннее обычного — поймайте это состояние."]],cool:[[100,"100м произвольно"],[200,"200м спина: работа двумя руками одновременно"]]},
      {n:13,vol:3000,note:"Мощность в кроле и мощность в комплексе — разные вещи",story:"Мощность в кроле и мощность в комплексе — разные вещи. В дельфине тяга идёт от корпуса, в брассе — от разведения и сведения рук, на спине — от постановки кисти сразу после входа. Здесь мы проходим все четыре стиля и в каждом ищем свою точку приложения силы.",warm:[[300,"300м комплекс по 75м, спокойно"],[200,"200м ноги комплекс без доски"],[100,"4х25м i20: по одному отрезку каждым стилем"]],main:[[300,"6х50м ноги дельфином в ластах, режим 1:10","Волна идёт от груди через таз к стопам. Это базовое движение для дельфина и заодно лучшая подготовка спины к работе."],[100,"4х25м i20: упражнение «руки дельфин / ноги кроль»"],[400,"8х50м по стилям со средними лопатками, режим 1:30: 2 дельфин, 2 спина, 2 брасс, 2 кроль","Короткие серии на каждый стиль — так лопатки не успевают перегрузить плечо. На дельфине следите, чтобы руки выходили из воды мимо бёдер, а не через сторону."],[200,"200м откуп спокойно на спине"],[400,"4х100м комплекс, режим 2:15, считаем гребки на каждой 25","Записывайте четыре числа. Стиль с самым большим числом гребков — ваша слабая точка в комплексе, ей и будете заниматься отдельно."],[400,"8х50м основной стиль, режим 1:20","Свой стиль на свежую голову после комплекса ощущается иначе. Сравните число гребков с тем, что было в серии по стилям."],[100,"100м откуп спокойно"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Кроль после комплекса всегда кажется лёгким — используйте это и постарайтесь снять лишний гребок."]],cool:[[200,"200м спина спокойно"],[100,"100м в трубке ноги брассом"]]},
      {n:14,vol:3000,note:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза…",story:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза, а гребок идёт под водой почти прямой траекторией. Любители на спине почти всегда гребут поверхностно и коротко. Разбираем это отдельной тренировкой — заодно спина хорошо разгружает плечо после кролевых объёмов.",warm:[[300,"300м спокойно: 150м спина + 150м кроль"],[200,"200м на спине: 100м «одна рука работает, вторая у бедра» + 100м «6-1-6»"],[100,"4х25м i20: упражнение «часы» — остановка руки в вертикальном положении"]],main:[[300,"6х50м ноги на спине в стрелочке, режим 1:20","Таз у поверхности, колени под водой. Если из воды показались колени, значит работа идёт вниз, а не назад."],[100,"4х25м i20: скайлинг на спине"],[400,"8х50м спина со средними лопатками, режим 1:20, считаем гребки","Кисть входит мизинцем, локоть уходит под воду и сгибается — прямой рукой на спине протянуть воду невозможно, лопатка это только подчеркнёт."],[200,"200м откуп спокойно"],[400,"8х50м спина с колобашкой, режим 1:20, мощно и плавно","Без ног на спине таз проваливается сразу. Держите его напряжением живота, взгляд строго вверх."],[400,"8х50м основной стиль, режим 1:20","Возвращаемся к своему стилю: после спины плечи разгружены и гребок обычно получается длиннее."],[100,"100м откуп спокойно"],[200,"8х25м спина без инвентаря на минимальное число гребков, i30","Замер тренировки — сегодня на спине. Записывайте его отдельно от кролевого, это разные цифры."]],cool:[[200,"200м кроль спокойно на минимальное число гребков"],[100,"100м произвольно"]]},
      {n:15,vol:3000,note:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё…",story:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё в одном занятии. Заканчивается она контрольным замером: четыре полтинника с фиксацией времени и числа гребков. Запишите обе цифры и вернитесь к ним через месяц — именно эта пара чисел показывает, растёт ли мощность.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м упражнения: 100м скайлинг + 100м на кулаках"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[300,"6х50м ноги, режим 1:20: три отрезка в ластах, три без","Сравните ощущение. Без ласт задача не догнать скорость, а сохранить то же положение таза."],[100,"4х25м i20: два отрезка «только первая фаза», два отрезка «только окончание гребка»"],[400,"8х50м кроль с чашечками, режим 1:20","Работа с сопротивлением перед замером. Держите число гребков, не разменивая длину на скорость."],[200,"200м откуп спокойно на спине"],[400,"8х50м кроль со средними лопатками и колобашкой, режим 1:15","Мощно и плавно, без ускорения. Это подготовка к замеру, а не соревнование с самим собой."],[400,"8х50м основной стиль, режим 1:20, считаем гребки","Свой стиль перед замером. Если число гребков здесь выросло больше чем на три по сравнению с началом тренировки, значит нагрузка была великовата — сбавьте усилие."],[100,"100м откуп спокойно"],[200,"4х50м кроль без инвентаря i60: контрольный замер — время и число гребков","Плывите мощно и плавно, а не на максимум. Показатель — это время при минимальном числе гребков, а не время любой ценой."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]}
    ]}
  }},
  b_vo:{name:"Восстановление",lede:"Пульс 20–22 удара за десять секунд. Лопаток и чашечек здесь нет сознательно.",levels:{
    vo_n:{level:"Новичок",vol:"1000 м",w:[
      {n:1,vol:1000,note:"После тяжёлой тренировки гребок остаётся коротким и суетливым — тело помнит вчерашнее напряжение",story:"После тяжёлой тренировки гребок остаётся коротким и суетливым — тело помнит вчерашнее напряжение. Сегодня задача вернуть длину: плывём медленно и следим только за тем, чтобы рука доходила до конца. Никакого секундомера, пульс 20–22 удара за десять секунд.",warm:[[100,"100м спокойно: 50м кроль + 50м спина, п:20-22"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[200,"200м кроль непрерывно, п:20-22, на минимальное число гребков — время не смотрим","Длина берётся из вытягивания вперёд и доведения руки до бедра, а не из усилия. Если начали уставать, вы плывёте слишком быстро."],[100,"100м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30, п:21: на первом полтиннике считаем гребки, дальше стараемся проплыть на один гребок меньше","Как только удержать число не выходит, оставайтесь на нём. Экономить за счёт задержки дыхания нельзя."],[100,"4х25м основной стиль i30, спокойно","На своём стиле плывите так, чтобы могли говорить. Сегодня скорость не нужна вообще."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:1000,note:"После тренировки с лопатками и колобашкой плечо устаёт больше всего",story:"После тренировки с лопатками и колобашкой плечо устаёт больше всего. Здесь мы его разгружаем: трубка убирает поворот головы, спина разворачивает плечо в другую сторону, а ноги дают телу поработать без участия рук.",warm:[[100,"100м спина спокойно, п:20-22"],[100,"4х25м i20: скайлинг"]],main:[[200,"200м в трубке спокойно, п:20-21 — голова не поворачивается, шея отдыхает","Без вращения корпуса легко провалить таз. Держите живот подобранным, тело в одну линию."],[100,"100м ноги на спине в стрелочке, спокойно"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Кисть входит мизинцем, локоть сгибается под водой. Тянуть не нужно — движение мягкое."],[100,"4х25м основной стиль i30, спокойно","Если плечо ещё забито, замените эту серию на спину — сегодня это не потеря."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:3,vol:1000,note:"После тренировки с большим количеством работы ногами забиваются стопа и икра",story:"После тренировки с большим количеством работы ногами забиваются стопа и икра. Сегодня ноги почти отдыхают: колобашка между ног, тело держат руки, темп мягкий от начала до конца.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"4х25м i20: скольжения с бортика до полной остановки"]],main:[[200,"200м руки с колобашкой, п:20-22 — ноги отдыхают","Никаких лопаток. Гребок мягкий, задача не тянуть воду, а прокачать плечи движением."],[100,"100м упражнение «плавание с паузой в момент входа руки»"],[200,"4х50м кроль i30, п:21, ноги работают едва заметно","Ноги нужны только для того, чтобы держать таз у поверхности. Любое усилие сверх этого сегодня лишнее."],[100,"4х25м основной стиль i30, спокойно","В брассе следите, чтобы колено не уходило под живот — там чаще всего появляется дискомфорт."]],cool:[[100,"100м скольжений с бортика"],[100,"100м спина спокойно"]]},
      {n:4,vol:1000,note:"Тренировка для дня между двумя обычными занятиями",story:"Тренировка для дня между двумя обычными занятиями. Здесь нет ни одной задачи на технику и ничего, что требует внимания: просто ровное спокойное плавание со сменой стилей. Такие занятия чаще всего пропускают — и зря, именно они и дают восстановиться.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"100м ноги с доской спокойно"]],main:[[200,"200м кроль непрерывно, п:20-21","Единственный ориентир — пульс. Если после отрезка он выше 22, следующие метры плывите медленнее."],[100,"100м упражнение «2 гребка правой, 2 гребка левой»"],[200,"200м спина непрерывно, п:20-21","Смена стиля работает как отдых: другие мышцы, другое положение плеча."],[100,"4х25м основной стиль i30, спокойно","Своим стилем в спокойном темпе плавать непривычно и полезно: техника видна лучше, чем на скорости."]],cool:[[100,"100м произвольно, дыхание свободное"],[100,"100м кроль на минимальное число гребков"]]},
      {n:5,vol:1000,note:"Иногда тренировка оказывается тяжелее, чем планировалось: непривычная серия, много быстрых от…",story:"Иногда тренировка оказывается тяжелее, чем планировалось: непривычная серия, много быстрых отрезков, усталость на следующий день. Это занятие как раз для такого случая — спина, трубка и мягкий кроль, никаких требований к себе.",warm:[[100,"100м спина спокойно, п:20-22"],[100,"4х25м i20: скольжения с бортика"]],main:[[200,"200м спина непрерывно, п:20-21","Спина раскрывает грудной отдел и возвращает плечу нормальную амплитуду после нагрузки."],[100,"100м в трубке спокойно"],[200,"4х50м кроль i30, п:21","Гребок мягкий, дыхание свободное. Не проверяйте сегодня, «как идёт» — это будет в следующий раз."],[100,"4х25м основной стиль i30, очень спокойно","Свой стиль плывём в половину привычного усилия. Это не тренировка стиля, это восстановление."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:6,vol:1000,note:"Дыхание — то, чем можно управлять сознательно, и через него проще всего успокоить организм",story:"Дыхание — то, чем можно управлять сознательно, и через него проще всего успокоить организм. Вся тренировка построена вокруг длинного полного выдоха: он снимает напряжение, выравнивает пульс и заодно улучшает положение тела в воде.",warm:[[100,"100м спокойно, дыхание через 3 гребка"],[100,"4х25м i20: длинный непрерывный выдох на всём отрезке"]],main:[[200,"200м кроль непрерывно, п:20-22, дыхание через 3 гребка, выдох длинный и полный","Выдох занимает всё время, пока лицо в воде. Задержка воздуха поднимает пульс и заставляет тело напрягаться."],[100,"100м спина: дыхание в ритме гребка, без задержек"],[200,"200м в трубке: выдох полностью в воду, вдох спокойный","В трубке дыхание слышно — используйте это как обратную связь. Вдох не должен быть жадным."],[100,"4х25м основной стиль i30, дыхание свободное","На брассе выдох короче по времени — начинайте его сразу, как голова уходит в воду."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:7,vol:1000,note:"Восстановительная тренировка — лучшее время для работы над положением тела: нет усталости, не…",story:"Восстановительная тренировка — лучшее время для работы над положением тела: нет усталости, нет спешки, можно чувствовать каждый метр. Сегодня много скольжений и спокойного плавания в вытянутом положении.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"4х25м i20: скольжение с бортика до полной остановки"]],main:[[200,"8х25м i20: толчок, длинное скольжение, дальше спокойно до бортика","Тело в стрелке: одна кисть на другой, голова между руками, взгляд вниз. Любой излом гасит скольжение мгновенно."],[100,"100м упражнение «ноги кролем на боку»"],[200,"200м кроль непрерывно, п:20-22, тело вытянуто, взгляд вниз","Голова продолжает линию позвоночника. Если смотрите вперёд, таз уходит вниз."],[100,"4х25м основной стиль i30, акцент на скольжение","В брассе скольжение — половина цикла. Не начинайте следующий гребок, пока тело ещё едет вперёд."]],cool:[[100,"100м спина спокойно"],[100,"100м скольжений с бортика"]]},
      {n:8,vol:1000,note:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть то…",story:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть только собственная длина. Сегодня это число нужно не для рекорда, а чтобы удерживать внимание на технике.",warm:[[100,"100м кроль спокойно с подсчётом гребков"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[200,"200м кроль непрерывно на минимальное число гребков, п:20-22 — время не смотрим","Если ради экономии гребков вы начали задерживать дыхание, это уже не восстановление. Дышите свободно."],[100,"100м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30 на минимальное число гребков, п:21","Число будет чуть хуже, чем на свежих силах. Это нормальная цена усталости, не расстраивайтесь."],[100,"4х25м основной стиль i30 на минимум гребков, спокойно","На своём стиле считайте циклы, а не движения рук — так проще не сбиться."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:9,vol:1000,note:"Упражнения обычно делают в разминке, наспех",story:"Упражнения обычно делают в разминке, наспех. Здесь наоборот: вся тренировка состоит из упражнений в спокойном темпе. Это единственный день, когда можно разобраться в движении, а не отработать его между сериями.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"4х25м i20: скайлинг"]],main:[[200,"200м упражнения на кроль: 100м на кулаках + 100м с паузой в момент входа руки"],[100,"100м упражнение на спине «одна рука работает, вторая у бедра»"],[200,"200м кроль непрерывно, п:20-22 — собираем ощущения вместе","Не старайтесь применить всё сразу. Выберите одну мысль и держите её до конца отрезка."],[100,"4х25м основной стиль i30, спокойно","Проверяем, перенеслось ли что-то из упражнений в обычное плавание. Если нет — это работа не одного дня."]],cool:[[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:10,vol:1000,note:"Спина — самый недооценённый стиль у начинающих и при этом лучший восстановительный",story:"Спина — самый недооценённый стиль у начинающих и при этом лучший восстановительный. Плечо работает в другой плоскости, шея не крутится, дыхание полностью свободное. Если после тяжёлой недели хочется просто поплавать — плавайте на спине.",warm:[[100,"100м спина спокойно, п:20-22"],[100,"4х25м i20: скайлинг на спине"]],main:[[200,"200м спина непрерывно, п:20-22","Таз у поверхности, взгляд строго вверх. Если из воды показались колени, работа ног пошла вниз, а не назад."],[100,"100м упражнение «одна рука работает, вторая вытянута за головой»"],[200,"200м ноги на спине в стрелочке, спокойно","Руки за головой, живот подобран. Движение мягкое, от бедра, без попытки разогнаться."],[100,"4х25м основной стиль i30, спокойно","После спины плечо разгружено, и гребок обычно получается длиннее, чем в начале тренировки."]],cool:[[100,"100м кроль спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:11,vol:1000,note:"Трубка убирает из плавания одно движение — поворот головы",story:"Трубка убирает из плавания одно движение — поворот головы. Кажется мелочью, но именно на нём держится половина напряжения в шее. Плавание в трубке ощущается непривычно спокойным, и это ровно то, что нужно в день восстановления.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"100м в трубке спокойно"]],main:[[200,"200м в трубке непрерывно, п:20-22","Без вращения головы легко провалить таз. Живот подобран, тело в одну линию, взгляд вниз."],[100,"100м в трубке руки с колобашкой, спокойно"],[200,"200м спина спокойно, без трубки","Обратите внимание, насколько привычнее стало дыхание после трубки — это и есть эффект тренировки."],[100,"4х25м основной стиль i30, спокойно"]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:12,vol:1000,note:"Иногда лучшее восстановление — просто плыть в одном темпе и ни о чём не думать",story:"Иногда лучшее восстановление — просто плыть в одном темпе и ни о чём не думать. Триста метров без остановок со сменой стиля каждые сто, пульс не выше 22. Для начинающего это ещё и хорошая проверка: получается ли плыть долго и спокойно.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"4х25м i20: упражнение на координацию"]],main:[[300,"300м непрерывно, п:20-22: каждые 100м смена стиля кроль / спина","Останавливаться нельзя, но и терпеть не нужно: если пульс пополз вверх, снижайте темп прямо на ходу."],[100,"100м откуп спокойно"],[100,"100м кроль на минимальное число гребков"],[100,"4х25м основной стиль i30, спокойно","После длинной работы свой стиль ощущается тяжелее. Плывите мягко, задача — закончить тренировку свежим."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:13,vol:1000,note:"Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая",story:"Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая. Сегодня плаваем всеми доступными стилями в спокойном темпе и без единого требования к технике переходов.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"4х25м i20: по одному отрезку спиной, брассом и кролем"]],main:[[200,"4х50м i40, п:20-22: 25м спина + 25м кроль, спокойно","Переход плывём как получится. Следим только за тем, чтобы дыхание оставалось свободным."],[100,"100м ноги с доской: 50м кроль + 50м брасс"],[200,"200м: 100м брасс + 100м кроль, спокойно","В брассе не форсируйте толчок — сегодня он мягкий, с длинным скольжением."],[100,"4х25м основной стиль i30","Свой стиль в конце всегда ощущается как отдых. Значит, остальные вы плыли не напрягаясь."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:14,vol:1000,note:"Чувство воды тренируется вниманием, а не нагрузкой",story:"Чувство воды тренируется вниманием, а не нагрузкой. Здесь мы намеренно убираем внешние ориентиры: не смотрим на часы, не считаем метры по разметке, а на коротких отрезках закрываем глаза. Странно ровно до первого раза.",warm:[[100,"100м спокойно: 50м кроль + 50м спина"],[100,"100м скайлинг"]],main:[[200,"200м кроль: считаем гребки до стенки и ориентируемся на счёт, а не на разметку дна","Обычно пловец подстраивается под дно и бортик. Здесь — только под собственный счёт."],[100,"4х25м i30: 12,5м с закрытыми глазами + 12,5м спокойно с открытыми","Только на свободной дорожке и вдоль разделительной, чтобы её можно было коснуться рукой. Теряете направление — открывайте глаза."],[200,"200м кроль непрерывно, п:20-22, внимание на ощущение воды в ладони","Ищите момент, когда ладонь «упирается». Это тот навык, который на скорости теряется первым."],[100,"4х25м основной стиль i30, спокойно"]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]],safe:"Отрезки с закрытыми глазами выполняются только на свободной дорожке, вдоль разделительной, чтобы её можно было коснуться рукой. Если рядом плывут люди — эту серию заменяем на обычное спокойное плавание."},
      {n:15,vol:1000,note:"У человека, который работает сидя и плавает в основном кролем, грудной отдел закрывается, а п…",story:"У человека, который работает сидя и плавает в основном кролем, грудной отдел закрывается, а плечо привыкает к одному положению. Эта тренировка возвращает амплитуду: брасс на спине, вытянутые положения, работа двумя руками одновременно.",warm:[[100,"100м спина спокойно, п:20-22"],[100,"4х25м i20: скольжение на спине в стрелочке"]],main:[[200,"200м брасс на спине спокойно","Руки идут через стороны в широкой амплитуде — именно это раскрывает грудной отдел. Если движение тугое, уменьшите размах, но не бросайте."],[100,"100м спина: работа двумя руками одновременно","Движение требует полного выноса плеча за голову. Двигайтесь медленно и не через боль."],[200,"200м кроль непрерывно, п:20-22","После работы на раскрытие пронос обычно идёт выше и свободнее. Не форсируйте, просто отметьте разницу."],[100,"4х25м основной стиль i30, спокойно","Заканчиваем своим стилем в мягком темпе. Тренировка про амплитуду, а не про метры."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]}
    ]},
    vo_s:{level:"Средний",vol:"1500 м",w:[
      {n:1,vol:1500,note:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету",story:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету. Задача сегодня вернуть длину: плывём медленно, следим только за тем, чтобы рука доходила до конца. Секундомер не нужен, пульс держим на 20–22 ударах за десять секунд.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[300,"300м кроль непрерывно, п:20-22, на минимальное число гребков — время не смотрим","Длина берётся из вытягивания вперёд и доведения руки до бедра, а не из усилия. Если начали уставать, вы плывёте слишком быстро."],[100,"100м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30, п:21: на первом полтиннике считаем гребки, дальше стараемся проплыть на один гребок меньше","Как только удержать число не выходит, оставайтесь на нём до конца серии. Экономить за счёт задержки дыхания нельзя."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно, без требований к темпу","На своём стиле после скоростной особенно тянет ускориться. Плывите так, чтобы могли говорить."]],cool:[[100,"100м спина: работа двумя руками одновременно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:1500,note:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки",story:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки. Здесь плечо разгружается полностью — трубка, спина и ноги. Кроль в координации сегодня почти не появляется, и это осознанно.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"4х25м i20: скайлинг"]],main:[[300,"300м в трубке спокойно, п:20-21 — голова не поворачивается, шея отдыхает","Без вращения корпуса легко провалить таз. Держите живот подобранным, тело в одну линию."],[200,"200м ноги: 100м с доской + 100м на спине, спокойно","Ноги здесь не тренируются, а прокачивают кровь через уставшие мышцы. Работа мягкая, без ускорений."],[100,"100м упражнение на спине «одна рука работает, вторая у бедра»"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Спина разворачивает плечо в другую сторону, чем кроль — именно поэтому она и восстанавливает."],[200,"4х50м основной стиль i30, спокойно","Если ваш стиль брасс или дельфин и плечо ещё забито, замените серию на спину — сегодня это не потеря."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:3,vol:1500,note:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра",story:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра. Сегодня ноги почти не работают — колобашка между ног, тело держат руки, темп мягкий от начала до конца.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"4х25м i20: скольжения с бортика до полной остановки"]],main:[[300,"300м руки с колобашкой, п:20-22 — ноги полностью отдыхают","Никаких лопаток. Гребок мягкий, задача не тянуть воду, а прокачать плечи движением."],[100,"100м упражнение «плавание с паузой в момент входа руки»"],[200,"4х50м кроль i30, п:21, ноги работают едва заметно","Ноги нужны только для того, чтобы держать таз у поверхности. Любое усилие сверх этого сегодня лишнее."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно","В брассе следите, чтобы колено не уходило под живот: после объёмной именно там появляется дискомфорт."]],cool:[[100,"100м скольжений с бортика"],[100,"100м спина спокойно"]]},
      {n:4,vol:1500,note:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа",story:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа. Здесь нет ни одной задачи на технику: просто ровное спокойное плавание со сменой стилей. Именно такие занятия чаще всего пропускают — и зря, они и делают неделю рабочей.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской спокойно"]],main:[[200,"200м кроль непрерывно, п:20-21","Единственный ориентир — пульс. Если после отрезка он выше 22, следующие метры плывите медленнее."],[100,"100м упражнение «2 гребка правой, 2 гребка левой»"],[200,"200м спина непрерывно, п:20-21","Смена стиля работает как отдых: другие мышцы, другое положение плеча."],[200,"200м в трубке спокойно"],[300,"6х50м основной стиль i30, спокойно","Своим стилем в спокойном темпе плавать непривычно и полезно: техника видна лучше, чем на скорости."]],cool:[[100,"100м произвольно, дыхание свободное"],[100,"100м кроль на минимальное число гребков"]]},
      {n:5,vol:1500,note:"После контрольного заплыва или просто очень тяжёлой тренировки главное — не добавить ещё",story:"После контрольного заплыва или просто очень тяжёлой тренировки главное — не добавить ещё. Занятие построено вокруг спины и трубки: они разгружают плечо и шею лучше всего. Никаких выводов о результате сегодня не делаем, просто плаваем.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"4х25м i20: скольжения с бортика"]],main:[[200,"200м спина непрерывно, п:20-21","После максимальной работы плечо перегружено спереди. Спина раскрывает грудной отдел и возвращает амплитуду."],[200,"200м в трубке спокойно"],[100,"100м упражнение на кроль из курса, спокойно"],[300,"6х50м кроль i30, п:21","Гребок мягкий, дыхание свободное. Если тянет проверить, «а как сейчас идёт» — не проверяйте, это будет завтра."],[200,"4х50м основной стиль i30, очень спокойно","Свой стиль плывём в половину привычного усилия. Это не тренировка стиля, это восстановление."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:6,vol:1500,note:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего…",story:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего успокоить организм. Вся тренировка построена вокруг длинного полного выдоха: он снимает напряжение, выравнивает пульс и заодно улучшает положение тела в воде.",warm:[[200,"200м спокойно, дыхание через 3 гребка"],[100,"4х25м i20: длинный непрерывный выдох на всём отрезке"]],main:[[300,"300м кроль непрерывно, п:20-22, дыхание через 3 гребка, выдох длинный и полный","Выдох занимает всё время, пока лицо в воде. Задержка воздуха поднимает пульс и заставляет тело напрягаться."],[100,"100м спина: дыхание в ритме гребка, без задержек"],[200,"200м в трубке: выдох полностью в воду, вдох спокойный","В трубке дыхание слышно — используйте это как обратную связь. Вдох не должен быть жадным."],[200,"200м упражнение «плавание на кулаках»"],[200,"4х50м основной стиль i30, дыхание свободное","На брассе выдох короче по времени — начинайте его сразу, как голова уходит в воду."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:7,vol:1500,note:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет устало…",story:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет усталости, нет спешки, можно чувствовать каждый метр. Сегодня много скольжений и длинного плавания в вытянутом положении.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"4х25м i20: скольжение с бортика до полной остановки"]],main:[[200,"8х25м i20: толчок, скольжение примерно до середины бассейна, дальше спокойно","Тело в стрелке: одна кисть на другой, голова между руками, взгляд вниз. Любой излом гасит скольжение мгновенно."],[100,"100м упражнение «ноги кролем на боку»"],[300,"300м кроль непрерывно, п:20-22, тело вытянуто, взгляд вниз","Голова продолжает линию позвоночника. Если смотрите вперёд, таз уходит вниз."],[200,"200м ноги на спине в стрелочке, спокойно"],[200,"4х50м основной стиль i30, акцент на скольжение","В брассе скольжение — половина цикла. Не начинайте следующий гребок, пока тело ещё едет вперёд."]],cool:[[100,"100м спина спокойно"],[100,"100м скольжений с бортика"]]},
      {n:8,vol:1500,note:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть то…",story:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть только собственная длина. Число будет хуже, чем на свежих силах, и это нормально — сегодня оно нужно не для рекорда, а чтобы удерживать внимание на технике.",warm:[[200,"200м спокойно: 100м кроль с подсчётом гребков + 100м спина"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[300,"300м кроль непрерывно на минимальное число гребков, п:20-22 — время не смотрим","Если ради экономии гребков вы начали задерживать дыхание или зависать в скольжении, это уже не восстановление."],[100,"100м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30 на минимальное число гребков, п:21","Разница с вашим лучшим результатом сегодня будет два-три гребка. Это нормальная цена усталости."],[200,"200м спина на минимальное число гребков"],[200,"4х50м основной стиль i30 на минимум гребков, спокойно","На своём стиле считайте циклы, а не движения рук — так проще не сбиться."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:9,vol:1500,note:"Упражнения обычно делают в разминке, наспех и уставшими",story:"Упражнения обычно делают в разминке, наспех и уставшими. Здесь наоборот: вся тренировка состоит из упражнений в спокойном темпе. Это единственный день, когда можно разобраться в движении, а не отработать его между сериями.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"4х25м i20: скайлинг"]],main:[[300,"300м упражнения на кроль: 100м на кулаках + 100м с акцентом на высокий локоть + 100м с паузой в момент входа руки"],[200,"200м упражнения на спину: 100м «6-1-6» + 100м одна рука работает, вторая у бедра"],[100,"100м упражнение на брасс: руки брасс / ноги кроль"],[200,"200м кроль непрерывно, п:20-22 — собираем ощущения вместе","Не старайтесь применить всё сразу. Выберите одну мысль и держите её до конца отрезка."],[200,"4х50м основной стиль i30, спокойно","Здесь проверяем, перенеслось ли что-то из упражнений в обычное плавание. Если нет — это работа не одного дня."]],cool:[[100,"100м спина спокойно"],[100,"100м кроль на минимальное число гребков"]]},
      {n:10,vol:1500,note:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный",story:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный. Плечо работает в другой плоскости, шея не крутится, дыхание полностью свободное. Если после тяжёлой недели хочется просто поплавать — плавайте на спине.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"4х25м i20: скайлинг на спине"]],main:[[300,"300м спина непрерывно, п:20-22","Таз у поверхности, взгляд строго вверх. Если из воды показались колени, работа ног пошла вниз, а не назад."],[100,"100м упражнение «одна рука работает, вторая вытянута за головой»"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Кисть входит мизинцем, локоть сгибается под водой. Прямой рукой на спине протянуть воду невозможно."],[200,"200м ноги на спине в стрелочке"],[200,"4х50м основной стиль i30, спокойно","После спины плечо разгружено, и обычно гребок получается длиннее, чем в начале тренировки."]],cool:[[100,"100м кроль спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:11,vol:1500,note:"Трубка убирает из плавания одно движение — поворот головы",story:"Трубка убирает из плавания одно движение — поворот головы. Кажется мелочью, но именно на нём держится половина напряжения в шее и плече. Тренировка в трубке ощущается непривычно спокойной, и это ровно то, что нужно после тяжёлой недели.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м в трубке спокойно"]],main:[[300,"300м в трубке непрерывно, п:20-22","Без вращения головы легко провалить таз. Живот подобран, тело в одну линию, взгляд вниз."],[200,"200м в трубке: 100м руки с колобашкой + 100м в координации","Колобашка плюс трубка — самое разгруженное положение в бассейне. Гребок мягкий, без попытки тянуть."],[100,"100м ноги в трубке с доской, спокойно"],[200,"200м спина спокойно, без трубки"],[200,"4х50м основной стиль i30, спокойно","Трубку снимаем. Обратите внимание, насколько привычнее стало дыхание — это и есть эффект тренировки."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно"]]},
      {n:12,vol:1500,note:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать",story:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать. Шестьсот метров без остановок, смена стиля каждые сто пятьдесят, пульс не выше 22. Голова разгружается не хуже мышц.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"4х25м i20: упражнение на координацию"]],main:[[600,"600м непрерывно, п:20-22: каждые 150м смена стиля кроль / спина","Останавливаться нельзя, но и терпеть не нужно: если пульс пополз вверх, снижайте темп прямо на ходу."],[200,"200м откуп спокойно"],[200,"4х50м основной стиль i30, спокойно","После длинной работы свой стиль ощущается тяжело. Плывите мягко, задача — закончить тренировку свежим."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:13,vol:1500,note:"Комплекс обычно означает работу: переходы, скорость, требования к технике",story:"Комплекс обычно означает работу: переходы, скорость, требования к технике. Сегодня всё наоборот — стили в спокойном темпе, без единого требования к стыкам. Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая.",warm:[[200,"200м комплекс по 50м, спокойно"],[100,"4х25м i20: по одному отрезку каждым стилем"]],main:[[300,"3х100м комплекс i40, п:20-22, без требований к переходам","Переходы плывём как получится. Следим только за тем, чтобы дыхание оставалось свободным на всех стилях."],[200,"200м ноги комплекс без доски, спокойно"],[200,"200м: 100м спина + 100м брасс, спокойно"],[100,"100м упражнение на самый неудобный для вас стиль"],[200,"4х50м основной стиль i30","Свой стиль в конце комплекса всегда ощущается как отдых. Значит, остальные вы плыли не напрягаясь."]],cool:[[100,"100м спина спокойно"],[100,"100м в трубке ноги брассом"]]},
      {n:14,vol:1500,note:"Чувство воды тренируется вниманием, а не нагрузкой",story:"Чувство воды тренируется вниманием, а не нагрузкой. Здесь мы намеренно убираем внешние ориентиры: не смотрим на часы, не считаем метры по разметке, а на коротких отрезках закрываем глаза. Странно ровно до первого раза.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м скайлинг"]],main:[[200,"200м кроль: считаем гребки до стенки и ориентируемся на счёт, а не на разметку дна","Обычно пловец подстраивается под дно и бортик. Здесь — только под собственный счёт."],[100,"4х25м i30: 12,5м с закрытыми глазами + 12,5м спокойно с открытыми","Только на свободной дорожке и вдоль разделительной, чтобы её можно было коснуться рукой. Теряете направление — открывайте глаза."],[300,"300м кроль непрерывно, п:20-22, внимание на ощущение воды в ладони","Ищите момент, когда ладонь «упирается». Это тот навык, который на скорости теряется первым."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно"]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]],safe:"Отрезки с закрытыми глазами выполняются только на свободной дорожке, вдоль разделительной, чтобы её можно было коснуться рукой. Если рядом плывут люди — эту серию заменяем на обычное спокойное плавание."},
      {n:15,vol:1500,note:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо…",story:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо привыкает к одному положению. Эта тренировка возвращает амплитуду: брасс на спине, длинные вытянутые положения, работа двумя руками одновременно.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"4х25м i20: скольжение на спине в стрелочке"]],main:[[200,"200м брасс на спине спокойно","Руки идут через стороны в широкой амплитуде — именно это раскрывает грудной отдел. Если движение тугое, уменьшите размах, но не бросайте."],[100,"100м упражнение «скольжение на спине в стрелочке»"],[300,"300м на спине: 150м двумя руками одновременно + 150м обычно","Работа двумя руками требует полного выноса плеча за голову. Двигайтесь медленно и не через боль."],[200,"200м кроль непрерывно, п:20-22","После работы на раскрытие пронос обычно идёт выше и свободнее. Не форсируйте, просто отметьте разницу."],[200,"4х50м основной стиль i30, спокойно","Заканчиваем своим стилем в мягком темпе. Тренировка про амплитуду, а не про метры."]],cool:[[100,"100м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]}
    ]},
    vo_p:{level:"Продвинутый",vol:"2000 м",w:[
      {n:1,vol:2000,note:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету",story:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету. Задача этой тренировки вернуть длину: плывём медленно, спокойно, следим только за тем, чтобы рука доходила до конца. Секундомер сегодня не нужен, а пульс держим на 20–22 ударах за десять секунд.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"100м ноги с доской спокойно"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[400,"400м кроль непрерывно, п:20-22, на минимальное число гребков — время не смотрим","Длина берётся из вытягивания вперёд и доведения руки до бедра, а не из усилия. Если начали уставать, вы плывёте слишком быстро."],[200,"200м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[300,"6х50м кроль i30, п:21: на первом полтиннике считаем гребки, дальше стараемся проплыть на один гребок меньше — и так, пока получается","Как только удержать число не выходит, оставайтесь на нём до конца серии. Экономить гребки за счёт задержки дыхания или зависания в скольжении нельзя — темп остаётся спокойным."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно, без требований к темпу","На своём стиле после скоростной особенно тянет ускориться. Плывите так, чтобы могли говорить."]],cool:[[200,"200м спина: работа двумя руками одновременно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:2000,note:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки",story:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки. Здесь мы плечо разгружаем полностью — трубка, спина и ноги. Кроль в координации сегодня почти не появляется, и это осознанно.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"100м ноги на спине в стрелочке"],[100,"4х25м i20: скайлинг"]],main:[[400,"400м в трубке спокойно, п:20-21 — голова не поворачивается, шея отдыхает","В трубке легко провалить таз, потому что нет вращения корпуса. Держите живот подобранным, тело в одну линию."],[300,"300м ноги: 150м с доской + 150м на спине, спокойно","Ноги здесь не тренируются, а прокачивают кровь через уставшие мышцы. Работа мягкая, без ускорений."],[200,"200м упражнение на спине «одна рука работает, вторая у бедра»"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Спина физиологически разворачивает плечо в другую сторону, чем кроль — именно поэтому она и восстанавливает."],[200,"4х50м основной стиль i30, спокойно","Если ваш стиль дельфин или брасс и плечо ещё забито, замените эту серию на спину — сегодня это не потеря."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно"]]},
      {n:3,vol:2000,note:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра",story:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра. Сегодня ноги почти не работают — колобашка между ног, тело держат руки, а вся тренировка идёт в мягком темпе.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м руки с колобашкой спокойно"],[100,"4х25м i20: скольжения с бортика до полной остановки"]],main:[[400,"400м руки с колобашкой, п:20-22 — ноги полностью отдыхают","Никаких лопаток. Гребок мягкий, задача не тянуть воду, а прокачать плечи движением."],[200,"200м упражнение «плавание с паузой в момент входа руки»"],[300,"6х50м кроль i30, п:21, ноги работают едва заметно","Ноги нужны только для того, чтобы держать таз у поверхности. Любое усилие сверх этого сегодня лишнее."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно","В брассе следите, чтобы колено не уходило под живот: после объёмной именно там чаще всего появляется дискомфорт."]],cool:[[100,"100м скольжений с бортика"],[200,"200м спина спокойно"]]},
      {n:4,vol:2000,note:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа",story:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа. Здесь нет ни одной задачи на технику и ни одного элемента, требующего внимания: просто ровное спокойное плавание со сменой стилей. Именно такие занятия чаще всего пропускают — и зря, они и делают неделю рабочей.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги с доской спокойно"]],main:[[300,"300м кроль непрерывно, п:20-21","Единственный ориентир — пульс. Если после отрезка он выше 22, следующие метры плывите медленнее."],[200,"200м упражнение «2 гребка правой, 2 гребка левой»"],[300,"300м спина непрерывно, п:20-21","Смена стиля здесь работает как отдых: другие мышцы, другое положение плеча."],[200,"200м в трубке спокойно"],[300,"6х50м основной стиль i30, спокойно","Своим стилем в спокойном темпе плавать непривычно и полезно: техника видна лучше, чем на скорости."]],cool:[[200,"200м произвольно, дыхание свободное"],[100,"100м кроль на минимальное число гребков"]]},
      {n:5,vol:2000,note:"После контрольного заплыва или соревнований организм получил максимальную нагрузку, и главное…",story:"После контрольного заплыва или соревнований организм получил максимальную нагрузку, и главное сейчас — не добавить ещё. Эта тренировка построена вокруг спины и трубки: они разгружают плечо и шею лучше всего. Никаких выводов о результате сегодня не делаем, просто плаваем.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"100м ноги с доской"],[100,"4х25м i20: скольжения с бортика"]],main:[[300,"300м спина непрерывно, п:20-21","После стартов плечо перегружено спереди. Спина раскрывает грудной отдел и возвращает нормальную амплитуду."],[300,"300м в трубке спокойно"],[200,"200м упражнение на кроль из курса, спокойно"],[300,"6х50м кроль i30, п:21","Гребок мягкий, дыхание свободное. Если тянет проверить, «а как сейчас идёт» — не проверяйте, это будет завтра."],[200,"4х50м основной стиль i30, очень спокойно","Свой стиль сегодня плывём в половину привычного усилия. Это не тренировка стиля, это восстановление."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно"]]},
      {n:6,vol:2000,note:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего…",story:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего успокоить организм. Вся тренировка построена вокруг длинного полного выдоха: он снимает напряжение, выравнивает пульс и заодно улучшает положение тела в воде.",warm:[[200,"200м спокойно, дыхание через 3 гребка"],[100,"100м спина спокойно"],[100,"4х25м i20: длинный непрерывный выдох на всём отрезке"]],main:[[400,"400м кроль непрерывно, п:20-22, дыхание через 3 гребка, выдох длинный и полный","Выдох должен занимать всё время, пока лицо в воде. Задержка воздуха поднимает пульс и заставляет тело напрягаться."],[200,"200м спина: дыхание в ритме гребка, без задержек"],[300,"300м в трубке: выдох полностью в воду, вдох спокойный","В трубке дыхание слышно — используйте это как обратную связь. Вдох не должен быть жадным."],[200,"200м упражнение «плавание на кулаках»"],[200,"4х50м основной стиль i30, дыхание свободное","На брассе и дельфине выдох короче по времени — начинайте его сразу, как голова уходит в воду."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:7,vol:2000,note:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет устало…",story:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет усталости, нет спешки, можно чувствовать каждый метр. Сегодня много скольжений и длинного плавания в вытянутом положении. Скорость не нужна вообще.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги на спине в стрелочке"],[100,"4х25м i20: скольжение с бортика до полной остановки"]],main:[[300,"12х25м i20: толчок, скольжение примерно до середины бассейна, дальше спокойно","Тело в стрелке: одна кисть на другой, голова между руками, взгляд вниз. Любой излом гасит скольжение мгновенно."],[200,"200м упражнение «ноги кролем на боку», по 25м на каждый бок"],[400,"400м кроль непрерывно, п:20-22, тело вытянуто, взгляд вниз","Голова продолжает линию позвоночника. Если смотрите вперёд, таз уходит вниз и вы тащите за собой воду."],[200,"200м ноги на спине в стрелочке, спокойно"],[200,"4х50м основной стиль i30, акцент на скольжение","В брассе скольжение — половина цикла. Не начинайте следующий гребок, пока тело ещё едет вперёд."]],cool:[[200,"200м спина спокойно"],[100,"100м скольжений с бортика"]]},
      {n:8,vol:2000,note:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть то…",story:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть только собственная длина. Число будет хуже, чем на свежих силах, и это нормально — сегодня оно нужно не для рекорда, а чтобы удерживать внимание на технике.",warm:[[200,"200м спокойно: 100м кроль с подсчётом гребков + 100м спина"],[100,"100м ноги с доской спокойно"],[100,"4х25м i20: плавание на минимальное число гребков"]],main:[[400,"400м кроль непрерывно на минимальное число гребков, п:20-22 — время не смотрим","Если ради экономии гребков вы начали задерживать дыхание или зависать в скольжении — это уже не восстановление. Дышите свободно."],[200,"200м упражнение «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[300,"6х50м кроль i30 на минимальное число гребков, п:21","Разница с вашим лучшим результатом сегодня будет два-три гребка. Это нормальная цена усталости, не расстраивайтесь."],[200,"200м спина на минимальное число гребков"],[200,"4х50м основной стиль i30 на минимум гребков, спокойно","На своём стиле считать сложнее — считайте циклы, а не движения рук, так проще не сбиться."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно"]]},
      {n:9,vol:2000,note:"Упражнения обычно делают в разминке, наспех и уставшими",story:"Упражнения обычно делают в разминке, наспех и уставшими. Здесь наоборот: вся тренировка состоит из упражнений в спокойном темпе, по всем стилям. Это единственный день, когда можно спокойно разобраться в движении, а не отработать его между сериями.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: скайлинг"]],main:[[300,"300м упражнения на кроль: 100м на кулаках + 100м с акцентом на высокий локоть + 100м с паузой в момент входа руки"],[300,"300м упражнения на спину: 100м «6-1-6» + 100м «часы» + 100м одна рука работает, вторая у бедра"],[200,"200м упражнения на брасс: 100м руки брасс / ноги кроль + 100м ноги брасс, руки в стрелку"],[300,"300м кроль непрерывно, п:20-22 — собираем ощущения вместе","После упражнений гребок ощущается иначе. Не старайтесь применить всё сразу, выберите одну мысль и держите её."],[200,"4х50м основной стиль i30, спокойно","Здесь проверяем, перенеслось ли что-то из упражнений в обычное плавание. Если нет — ничего страшного, это работа не одного дня."]],cool:[[200,"200м спина спокойно"],[100,"100м на минимальное число гребков"]]},
      {n:10,vol:2000,note:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный",story:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный. Плечо работает в другой плоскости, шея не крутится, дыхание полностью свободное. Если после тяжёлой недели хочется просто поплавать — плавайте на спине.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"100м ноги на спине с руками вдоль тела"],[100,"4х25м i20: скайлинг на спине"]],main:[[400,"400м спина непрерывно, п:20-22","Таз у поверхности, взгляд строго вверх. Если из воды показались колени, работа ног пошла вниз, а не назад."],[200,"200м упражнение «одна рука работает, вторая вытянута за головой»"],[300,"6х50м спина i30, п:21, гребок длинный и мягкий","Кисть входит мизинцем, локоть сгибается под водой. Прямой рукой на спине протянуть воду невозможно — и сегодня не нужно."],[200,"200м ноги на спине в стрелочке"],[200,"4х50м основной стиль i30, спокойно","Возврат к своему стилю после спины: плечо разгружено, и обычно гребок получается длиннее, чем в начале тренировки."]],cool:[[200,"200м кроль спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:11,vol:2000,note:"Трубка убирает из плавания одно движение — поворот головы",story:"Трубка убирает из плавания одно движение — поворот головы. Кажется мелочью, но именно на нём держится половина напряжения в шее и плече. Целая тренировка в трубке ощущается непривычно спокойной, и это ровно то, что нужно после тяжёлой недели.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м в трубке спокойно"],[100,"4х25м i20: скольжения с бортика"]],main:[[400,"400м в трубке непрерывно, п:20-22","Без вращения головы легко провалить таз. Живот подобран, тело в одну линию, взгляд вниз."],[300,"300м в трубке: 150м руки с колобашкой + 150м в координации","Колобашка плюс трубка — самое разгруженное положение в бассейне. Гребок мягкий, без попытки тянуть."],[200,"200м ноги в трубке с доской, спокойно"],[200,"200м спина спокойно, без трубки"],[200,"4х50м основной стиль i30, спокойно","Трубку снимаем. Обратите внимание, насколько привычнее стало дыхание — это и есть эффект тренировки."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно"]]},
      {n:12,vol:2000,note:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать",story:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать. Тысяча метров без остановок, смена стиля каждые двести, пульс не выше 22. Голова разгружается не хуже мышц, а это после тяжёлой недели важно не меньше.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги с доской"],[100,"4х25м i20: упражнение на координацию"]],main:[[1000,"1000м непрерывно, п:20-22: каждые 200м смена стиля кроль / спина","Останавливаться нельзя, но и терпеть не нужно: если пульс пополз вверх, снижайте темп прямо на ходу. Дистанция важнее скорости."],[100,"100м откуп спокойно"],[200,"4х50м основной стиль i30, спокойно","После длинной работы свой стиль ощущается тяжело. Плывите мягко, задача — закончить тренировку свежим."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:13,vol:2000,note:"Комплекс обычно означает работу: переходы, скорость, требования к технике",story:"Комплекс обычно означает работу: переходы, скорость, требования к технике. Сегодня всё наоборот — четыре стиля в спокойном темпе, без единого требования к стыкам. Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая.",warm:[[200,"200м комплекс по 50м, спокойно"],[100,"100м ноги комплекс без доски"],[100,"4х25м i20: по одному отрезку каждым стилем"]],main:[[400,"4х100м комплекс i40, п:20-22, без требований к переходам","Переходы плывём как получится. Единственное, за чем следим, — чтобы дыхание оставалось свободным на всех четырёх стилях."],[200,"200м ноги комплекс без доски, спокойно"],[300,"300м: 100м спина + 100м брасс + 100м кроль, спокойно"],[200,"200м упражнения: по 100м на два самых неудобных для вас стиля"],[200,"4х50м основной стиль i30","Свой стиль в конце комплекса всегда ощущается как отдых. Это хороший знак: значит, остальные три вы плыли не напрягаясь."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно"]]},
      {n:14,vol:2000,note:"Чувство воды тренируется вниманием, а не нагрузкой",story:"Чувство воды тренируется вниманием, а не нагрузкой. Здесь мы намеренно убираем внешние ориентиры: не смотрим на часы, не считаем метры по разметке, а на коротких отрезках закрываем глаза. Тренировка кажется странной ровно до первого раза — а потом становится любимой.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м скайлинг"],[100,"4х25м i20: упражнение «плавание на кулаках»"]],main:[[300,"300м кроль: считаем гребки до стенки и ориентируемся на счёт, а не на разметку дна","Обычно пловец подстраивается под дно и бортик. Здесь — только под собственный счёт, и стенка каждый раз оказывается там, где вы её не ждали."],[200,"8х25м i30: 12,5м с закрытыми глазами + 12,5м спокойно с открытыми","Только на свободной дорожке и вдоль разделительной, чтобы её можно было коснуться рукой. Как только теряете направление — открывайте глаза."],[400,"400м кроль непрерывно, п:20-22, внимание на ощущение воды в ладони","Ищите момент, когда ладонь «упирается». Это тот самый навык, который на скорости теряется первым."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно","На своём стиле повторите то же наблюдение: где именно рука находит опору и в какой момент теряет её."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно, дыхание свободное"]],safe:"Отрезки с закрытыми глазами выполняются только на свободной дорожке, вдоль разделительной, чтобы её можно было коснуться рукой. Если рядом плывут люди — эту серию заменяем на обычное спокойное плавание."},
      {n:15,vol:2000,note:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо…",story:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо привыкает к одному положению. Эта тренировка возвращает амплитуду: брасс на спине, длинные вытянутые положения, работа двумя руками одновременно. После неё гребок обычно ощущается свободнее.",warm:[[200,"200м спина спокойно, п:20-22"],[100,"100м ноги на спине в стрелочке"],[100,"4х25м i20: скольжение на спине в стрелочке"]],main:[[300,"300м брасс на спине спокойно","Руки идут через стороны в широкой амплитуде — именно это раскрывает грудной отдел. Если движение тугое, уменьшите размах, но не бросайте."],[200,"200м упражнение «скольжение на спине в стрелочке»"],[300,"300м на спине: 150м двумя руками одновременно + 150м обычно","Работа двумя руками требует полного выноса плеча за голову. Двигайтесь медленно и не через боль."],[300,"300м кроль непрерывно, п:20-22","После работы на раскрытие пронос обычно идёт выше и свободнее. Не форсируйте, просто отметьте разницу."],[200,"4х50м основной стиль i30, спокойно","Заканчиваем своим стилем в мягком темпе. Никаких требований к скорости — тренировка про амплитуду, а не про метры."]],cool:[[200,"200м спина спокойно"],[100,"100м произвольно, дыхание свободное"]]}
    ]}
  }}
};
